INSERT INTO [dbo].[Section] ([UpdateDate],[RevisionID],[ID],[ParentID],[DisplayOrder],[Title],[SectionContentTypeID],[TextContent],[IsInternalSection],[DisplayRateCode],[RevisionUniqueSectionId]) VALUES (GETDATE(),1,1,null,0,'Introduction',1,'',0,0,1);
INSERT INTO [dbo].[Section] ([UpdateDate],[RevisionID],[ID],[ParentID],[DisplayOrder],[Title],[SectionContentTypeID],[TextContent],[IsInternalSection],[DisplayRateCode],[RevisionUniqueSectionId]) VALUES (GETDATE(),1,2,1,0,null,2,'<p>This document describes the elements of the accounting system used by Lockheed Martin Space Systems Company (LMSSC) and how those elements are calculated and displayed in formal cost proposals.&nbsp; This document is an aide in understanding the Forward Pricing Rate Agreements (FPRAs) and also explains common LMSSC Estimating rates and disclosures.&nbsp;&nbsp; The FPRAs were developed through an IPT process teaming LMSSC, DCMA with inputs from DCAA.&nbsp;&nbsp; Individual proposals will display only the applicable items from this document.&nbsp; The document is intended for use by LMSSC, PCOs, ACOs, oversight agencies, and government cost/price analysts.</p>',0,0,2);
