INSERT INTO [dbo].[Section] ([UpdateDate],[RevisionID],[ID],[ParentID],[DisplayOrder],[Title],[SectionContentTypeID],[TextContent],[IsInternalSection],[DisplayRateCode],[RevisionUniqueSectionId]) VALUES (GETDATE(),1,7,1,3,'CAS 401 - Consistency of Accounting & Estimating Methodology',1,'',0,0,7);
INSERT INTO [dbo].[Section] ([UpdateDate],[RevisionID],[ID],[ParentID],[DisplayOrder],[Title],[SectionContentTypeID],[TextContent],[IsInternalSection],[DisplayRateCode],[RevisionUniqueSectionId]) VALUES (GETDATE(),1,8,7,0,null,2,'<p>All cost estimates, whether for internal purposes or for submittal to a customer, will be priced consistent, in all material aspects, with accounting practices described in the latest revision of the LM Space Systems Company (LMSSC) Cost Accounting Standards Disclosure Statement (CAS/DS).&nbsp; Proposals to the United States Government (USG) for contract actions under Federal Acquisition Regulations (FAR) Part 15 will be priced in accordance with USG cost accounting standards.&nbsp; This includes proposals submitted as a prime contractor, a subcontractor or a supporting interdivisional unit to another Lockheed Martin entity.&nbsp;</p>',0,0,8);
INSERT INTO [dbo].[Section] ([UpdateDate],[RevisionID],[ID],[ParentID],[DisplayOrder],[Title],[SectionContentTypeID],[TextContent],[IsInternalSection],[DisplayRateCode],[RevisionUniqueSectionId]) VALUES (GETDATE(),1,9,1,4,'Cost Accounting Standards Board (CASB) Disclosure Statement',1,'',0,0,9);
INSERT INTO [dbo].[Section] ([UpdateDate],[RevisionID],[ID],[ParentID],[DisplayOrder],[Title],[SectionContentTypeID],[TextContent],[IsInternalSection],[DisplayRateCode],[RevisionUniqueSectionId]) VALUES (GETDATE(),1,10,9,0,null,2,'<p style="margin-left: .5in;">NAME AND ADDRESS OF COGNIZANT ACO WHERE FILED:</p> <p style="margin-left: .5in;">Defense Contract Management Agency (DCMA)</p> <p style="margin-left: .5in;">Lockheed Martin Space Systems Company</p> <ol> <li style="margin-left: .5in;">O. Box 179, Denver, CO&nbsp; 80201-0179</li> </ol> <p style="margin-left: .5in;">Attn: DACO, Cindy Russ</p> <p><span style="color: #1f497d;">&nbsp;</span></p> <p style="margin-left: .5in;">Lockheed Martin Space Systems Company Home Office &nbsp;</p> <p style="margin-left: .5in;">Revision #1 dated February 1, 2016, Effective January 01, 2016</p> <p style="margin-left: .5in;">(no changes in 2017)</p> <p style="margin-left: .5in;">&nbsp;</p> <p style="margin-left: .5in;">Lockheed Martin Space Systems Company Core Segment &nbsp;</p> <p style="margin-left: .5in;">Revision #17 dated January 1, 2017, Effective January 01, 2017</p> <p style="margin-left: .5in;">&nbsp;</p> <p style="margin-left: .5in;">Lockheed Martin Space Systems Company Services Segment &nbsp;</p> <p style="margin-left: .5in;">Revision #2017 dated January 1, 2017, Effective January 01, 2017</p> <p style="margin-left: .5in;">&nbsp;</p> <p style="margin-left: .5in;">Latest Adequacy (Rev. #15) September 29, 2015</p> <p>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;</p> <p style="margin-left: .5in;">The information in this proposal was developed consistent with accounting practices and the latest proposed Lockheed Martin Space Systems Company Accounting Disclosure Statements, submitted February 1, 2016 (Home Office), effective January 1, 2017 (Core Segment) and January 1, 2017 (Services Segment).</p>',0,0,10);
INSERT INTO [dbo].[Section] ([UpdateDate],[RevisionID],[ID],[ParentID],[DisplayOrder],[Title],[SectionContentTypeID],[TextContent],[IsInternalSection],[DisplayRateCode],[RevisionUniqueSectionId]) VALUES (GETDATE(),1,11,1,5,'Open CAS Non-Compliance Issues',1,'',0,0,11);
INSERT INTO [dbo].[Section] ([UpdateDate],[RevisionID],[ID],[ParentID],[DisplayOrder],[Title],[SectionContentTypeID],[TextContent],[IsInternalSection],[DisplayRateCode],[RevisionUniqueSectionId]) VALUES (GETDATE(),1,12,11,0,null,2,'<p>There are no open LMSSC non-compliance issues.</p>',0,0,12);
INSERT INTO [dbo].[Section] ([UpdateDate],[RevisionID],[ID],[ParentID],[DisplayOrder],[Title],[SectionContentTypeID],[TextContent],[IsInternalSection],[DisplayRateCode],[RevisionUniqueSectionId]) VALUES (GETDATE(),1,13,null,1,'Overhead, G&A, Fringe Benefits and Facilities Cost of Money Rates',1,'',0,0,13);
INSERT INTO [dbo].[Section] ([UpdateDate],[RevisionID],[ID],[ParentID],[DisplayOrder],[Title],[SectionContentTypeID],[TextContent],[IsInternalSection],[DisplayRateCode],[RevisionUniqueSectionId]) VALUES (GETDATE(),1,14,13,0,null,2,'<p><span style="text-decoration: none; text-underline: none;">Overhead expenses are collected in pools and their costs are distributed to direct labor dollars and all costs associated with job-shoppers incurred by organizations which benefit from the overhead expenses.</span></p> <p style="tab-stops: -.5in;">The 2013 actual overhead rates, reference LMSSC-14-007 memo dated January 9, 2014</p> <p style="tab-stops: -.5in;">The 2013 actual CAS 414 G&amp;A Rate, reference LMSSC-14-023 memo dated January 29, 2014</p> <p style="tab-stops: -.5in;">The 2014 actual overhead rates, reference LMSSC-15-001 memo dated January 9, 2015</p> <p style="tab-stops: -.5in;">The 2015 actual overhead rates, reference LMSSC-16-001 memo dated January 8, 2016</p> <p style="tab-stops: -.5in;">The 2016 actual overhead rates, reference LMSSC-17-003 memo dated January 11, 2017</p> <p style="tab-stops: -.5in;">&nbsp;</p> <p style="tab-stops: -.5in;">The 2017 &ndash; 2019 Services Segments Overhead, G&amp;A, Fringe and CAS 414 Rates, reference</p> <p style="tab-stops: -.5in;">LMSSC-16-008 (Services Segment) letter, dated February 1, 2016 (Submitted, Not Negotiated)</p> <p style="tab-stops: -.5in;">The 2017 &ndash; 2019 Core Segment Overhead, G&amp;A, Fringe and CAS 414 Rates, reference FPRA 16-04&nbsp;&nbsp;&nbsp;&nbsp; dated July 8, 2016</p> <p>&nbsp;</p> <p>Embedded Letters</p> <p>&nbsp;(Attachments To be added by Central Estimating)</p> <p>&nbsp;</p> <p>CASB-CMF Forms</p> <p>&nbsp;&nbsp;(Attachments To be added by Central Estimating)</p> <p>&nbsp;</p>',0,0,14);
INSERT INTO [dbo].[Section] ([UpdateDate],[RevisionID],[ID],[ParentID],[DisplayOrder],[Title],[SectionContentTypeID],[TextContent],[IsInternalSection],[DisplayRateCode],[RevisionUniqueSectionId]) VALUES (GETDATE(),1,15,13,1,'Development Overhead',1,'',0,0,15);
INSERT INTO [dbo].[Section] ([UpdateDate],[RevisionID],[ID],[ParentID],[DisplayOrder],[Title],[SectionContentTypeID],[TextContent],[IsInternalSection],[DisplayRateCode],[RevisionUniqueSectionId]) VALUES (GETDATE(),1,16,15,0,null,2,'<p style="margin-bottom: .0001pt;">The development overhead pool includes the indirect costs of cost centers whose efforts are utilized primarily in the performance or support of Engineering.&nbsp;&nbsp; Indirect Labor and Non-labor Costs included:&nbsp; &nbsp;Development Overhead Service Orders, Development components of Enterprise cost reduction initiatives and related metrics, Development Command Media, process documentation and Audits, technical library, Restructure education, Knowledge Transfer, Training for Development Pool overhead personnel, Development overhead planning and management in functional areas (Excludes line-of-business overhead planning and reporting), Development fixed assets, Development common equipment expense (including rentals), Lost Productive Time, Core Segment administration of LM Commit/Performance Management activities, Identification of enterprise Common/Preferred Parts, Union Business, Allocations from Services Total, Services Local and U&amp;O.</p> <p style="margin-bottom: .0001pt;">&nbsp;</p> <p style="margin-bottom: .0001pt;">Base: &nbsp;Direct labor dollars in Activity Types identified as Development Pool, Job-shopper costs and applicable labor dollars generated by service centers.</p>',0,0,16);
INSERT INTO [dbo].[Section] ([UpdateDate],[RevisionID],[ID],[ParentID],[DisplayOrder],[Title],[SectionContentTypeID],[TextContent],[IsInternalSection],[DisplayRateCode],[RevisionUniqueSectionId]) VALUES (GETDATE(),1,17,15,1,null,3,'',0,0,17);
INSERT INTO [dbo].[Section] ([UpdateDate],[RevisionID],[ID],[ParentID],[DisplayOrder],[Title],[SectionContentTypeID],[TextContent],[IsInternalSection],[DisplayRateCode],[RevisionUniqueSectionId]) VALUES (GETDATE(),1,18,15,2,null,2,'<p>2017-2019 rates reference FPRA-16-04, dated July 8, 2016</p>',0,0,18);
INSERT INTO [dbo].[Section] ([UpdateDate],[RevisionID],[ID],[ParentID],[DisplayOrder],[Title],[SectionContentTypeID],[TextContent],[IsInternalSection],[DisplayRateCode],[RevisionUniqueSectionId]) VALUES (GETDATE(),1,19,13,2,'Production Overhead',1,'',0,0,19);
INSERT INTO [dbo].[Section] ([UpdateDate],[RevisionID],[ID],[ParentID],[DisplayOrder],[Title],[SectionContentTypeID],[TextContent],[IsInternalSection],[DisplayRateCode],[RevisionUniqueSectionId]) VALUES (GETDATE(),1,20,19,0,null,2,'<p style="margin: 0in 0in 0pt;">The production overhead pool includes the indirect costs of cost centers whose efforts are utilized primarily in the production effort or in support of the production effort. Indirect Labor and Non-labor Costs included: Production Overhead Service Orders, Production components of Enterprise cost reduction initiatives and related metrics, Production Command Media, Common manufacturing standards, methods and processes, Metrology, Restructure, Feasibility studies related to in-house manufacturing, Training for Production Overhead Pool personnel, Production fixed assets, common manufacturing aids and tools, Production common equipment expense (including small tools, Production consumables and rentals), Lost Productive Time, Union Business, Core Segment administration of LM Commit/Performance Management activities, Allocations from Services Total, Services Local, and U&amp;O and Shipping Supplies.</p> <p style="margin: 0in 0in 0pt;">&nbsp;</p> <p style="margin: 0in 0in 0pt;">Base: Direct labor dollars in Activity Types identified as Production Pool, Job-shopper costs; and applicable labor dollars generated by service centers.</p>',0,0,20);
INSERT INTO [dbo].[Section] ([UpdateDate],[RevisionID],[ID],[ParentID],[DisplayOrder],[Title],[SectionContentTypeID],[TextContent],[IsInternalSection],[DisplayRateCode],[RevisionUniqueSectionId]) VALUES (GETDATE(),1,21,19,1,null,3,'',0,0,21);
