INSERT INTO [dbo].[Section] ([UpdateDate],[RevisionID],[ID],[ParentID],[DisplayOrder],[Title],[SectionContentTypeID],[TextContent],[IsInternalSection],[DisplayRateCode],[RevisionUniqueSectionId]) VALUES (GETDATE(),1,39,13,7,'SSC Core Segment Procurement Overhead',1,'',0,0,39);
INSERT INTO [dbo].[Section] ([UpdateDate],[RevisionID],[ID],[ParentID],[DisplayOrder],[Title],[SectionContentTypeID],[TextContent],[IsInternalSection],[DisplayRateCode],[RevisionUniqueSectionId]) VALUES (GETDATE(),1,40,39,0,null,2,'<p>The SSC Core Segment Procurement non-labor costs include:&nbsp; Occupancy costs for onsite suppliers and material storage, allocations from the SSC Common Procurement Overhead Pool, Low dollar- high volume (bulk) common material.</p> <p>Base:&nbsp; SSC Core Segment direct material, direct subcontract and consultant costs.&nbsp; Excludes IWTA and Job Shoppers.&nbsp; Also excludes such items not procured by Space Systems Company to support the THAAD program or contracts.</p>',0,0,40);
INSERT INTO [dbo].[Section] ([UpdateDate],[RevisionID],[ID],[ParentID],[DisplayOrder],[Title],[SectionContentTypeID],[TextContent],[IsInternalSection],[DisplayRateCode],[RevisionUniqueSectionId]) VALUES (GETDATE(),1,41,39,1,null,3,'',0,0,41);
