INSERT INTO [dbo].[Section] ([UpdateDate],[RevisionID],[ID],[ParentID],[DisplayOrder],[Title],[SectionContentTypeID],[TextContent],[IsInternalSection],[DisplayRateCode],[RevisionUniqueSectionId]) VALUES (GETDATE(),1,43,13,8,'SSC Core Segment General and Administrative (G&A)',1,'',0,0,43);
INSERT INTO [dbo].[Section] ([UpdateDate],[RevisionID],[ID],[ParentID],[DisplayOrder],[Title],[SectionContentTypeID],[TextContent],[IsInternalSection],[DisplayRateCode],[RevisionUniqueSectionId]) VALUES (GETDATE(),1,44,43,0,null,2,'<p>The SSC Core Segment G&amp;A pool includes indirect cost (Labor and Non-labor) of cost centers required for the performance and support of SSC Core Segment G&amp;A Functions, i.e., Chief Engineer, &nbsp;Marketing and Market Analysis, Training for G&amp;A Pool personnel. Corporate research costs, IR&amp;D/B&amp;P projects burdened with applicable overheads, inter-divisional and inter-company costs.</p> <p style="margin: 0in 0in 0pt;">Base:&nbsp; SSC Core Segment direct labor dollars, including purchased labor.</p>',0,0,44);
INSERT INTO [dbo].[Section] ([UpdateDate],[RevisionID],[ID],[ParentID],[DisplayOrder],[Title],[SectionContentTypeID],[TextContent],[IsInternalSection],[DisplayRateCode],[RevisionUniqueSectionId]) VALUES (GETDATE(),1,45,43,1,null,3,'',0,0,45);
INSERT INTO [dbo].[Section] ([UpdateDate],[RevisionID],[ID],[ParentID],[DisplayOrder],[Title],[SectionContentTypeID],[TextContent],[IsInternalSection],[DisplayRateCode],[RevisionUniqueSectionId]) VALUES (GETDATE(),1,46,43,2,null,2,'<p>2017-2019 rates reference FPRA-16-04, dated July 8, 2016</p>',0,0,46);
INSERT INTO [dbo].[Section] ([UpdateDate],[RevisionID],[ID],[ParentID],[DisplayOrder],[Title],[SectionContentTypeID],[TextContent],[IsInternalSection],[DisplayRateCode],[RevisionUniqueSectionId]) VALUES (GETDATE(),1,47,13,9,'Fringe Corporate Benefits / Tier 1',1,'',0,0,47);
INSERT INTO [dbo].[Section] ([UpdateDate],[RevisionID],[ID],[ParentID],[DisplayOrder],[Title],[SectionContentTypeID],[TextContent],[IsInternalSection],[DisplayRateCode],[RevisionUniqueSectionId]) VALUES (GETDATE(),1,48,47,0,null,2,'<p>Fringe Corporate Benefits include: Costs incurred for SSC Core Segment, SSC Services Segment and SSC Home Office employees in the Corporate Benefits structure: Incentive Compensation and Special Recognition Awards (SRA), Retiree Medical, Group insurance, Workers Compensation, Vacations, Holidays, Hourly Sick Leave, Unemployment Insurance, Social Security, Hourly and Salary Pensions, Deferred Compensation, Supplemental Savings Plan and Administrative Fees.</p> <p>Cost for Fringe benefits follows direct and indirect labor dollars.</p> <p>Base:&nbsp; Direct labor dollars of all SSC Core Segment, SSC Services Segment and SSC Home Office employees in the Corporate Benefits structure (excludes labor included in fringe benefits and Contract Labor), including Michoud Operations employees.</p>',0,0,48);
INSERT INTO [dbo].[Section] ([UpdateDate],[RevisionID],[ID],[ParentID],[DisplayOrder],[Title],[SectionContentTypeID],[TextContent],[IsInternalSection],[DisplayRateCode],[RevisionUniqueSectionId]) VALUES (GETDATE(),1,49,47,1,null,3,'',0,0,49);
INSERT INTO [dbo].[Section] ([UpdateDate],[RevisionID],[ID],[ParentID],[DisplayOrder],[Title],[SectionContentTypeID],[TextContent],[IsInternalSection],[DisplayRateCode],[RevisionUniqueSectionId]) VALUES (GETDATE(),1,50,47,2,null,2,'<p>2017-2019 rates reference FPRA-16-04, dated July 8, 2016</p>',0,0,50);
INSERT INTO [dbo].[Section] ([UpdateDate],[RevisionID],[ID],[ParentID],[DisplayOrder],[Title],[SectionContentTypeID],[TextContent],[IsInternalSection],[DisplayRateCode],[RevisionUniqueSectionId]) VALUES (GETDATE(),1,51,13,10,'FISAC Overhead ',1,'',0,0,51);
INSERT INTO [dbo].[Section] ([UpdateDate],[RevisionID],[ID],[ParentID],[DisplayOrder],[Title],[SectionContentTypeID],[TextContent],[IsInternalSection],[DisplayRateCode],[RevisionUniqueSectionId]) VALUES (GETDATE(),1,52,51,0,null,2,'<p style="margin: 0in 0in 0pt; text-indent: 0.5in;">(FISAC - Future Intercontinental Ballistic Missile Sustainment and Acquisition Concept)</p> <p style="margin: 0in 0in 0pt;"><span style="font-family: ''Times'',serif;">&nbsp;</span></p> <p style="margin: 0in 0in 0pt;">The FISAC pool includes the indirect costs of the Offsite Miscellaneous cost centers. Indirect labor and non-labor costs included: Facility and related Use and Occupancy Costs at FISAC Operations, Utah, Restructure, Union Business, Salary Continuation, Allocations from Service Total Expense Pool.</p> <p style="margin: 0in 0in 0pt;">&nbsp;</p> <p style="margin: 0in 0in 0pt;">Base: Direct labor dollars of the cost centers/departments assigned to the FISAC Pool.</p>',0,0,52);
INSERT INTO [dbo].[Section] ([UpdateDate],[RevisionID],[ID],[ParentID],[DisplayOrder],[Title],[SectionContentTypeID],[TextContent],[IsInternalSection],[DisplayRateCode],[RevisionUniqueSectionId]) VALUES (GETDATE(),1,53,51,1,null,3,'',0,0,53);
INSERT INTO [dbo].[Section] ([UpdateDate],[RevisionID],[ID],[ParentID],[DisplayOrder],[Title],[SectionContentTypeID],[TextContent],[IsInternalSection],[DisplayRateCode],[RevisionUniqueSectionId]) VALUES (GETDATE(),1,54,51,2,null,2,'<p>2017-2019 rates reference FPRA-16-04, dated July 8, 2016</p>',0,0,54);
INSERT INTO [dbo].[Section] ([UpdateDate],[RevisionID],[ID],[ParentID],[DisplayOrder],[Title],[SectionContentTypeID],[TextContent],[IsInternalSection],[DisplayRateCode],[RevisionUniqueSectionId]) VALUES (GETDATE(),1,55,13,11,'Offsite Services Overhead',1,'',0,0,55);
INSERT INTO [dbo].[Section] ([UpdateDate],[RevisionID],[ID],[ParentID],[DisplayOrder],[Title],[SectionContentTypeID],[TextContent],[IsInternalSection],[DisplayRateCode],[RevisionUniqueSectionId]) VALUES (GETDATE(),1,56,55,0,null,2,'<p style="margin: 0in 0in 0pt;">The Onsite Services includes the indirect costs of cost centers whose efforts are utilized primarily in the performance or support of SSC Services Segment contracts performed at onsite facilities. Onsite facilities are defined as SSC company-owned or leased building locations where effort is performed.</p> <p style="margin: 0in 0in 0pt;">&nbsp;</p> <p style="margin: 0in 0in 0pt;">Indirect Labor and Non-labor costs included: Onsite Service Command Media, restructure, knowledge transfer, training for onsite service pool overhead personnel, onsite Services overhead planning and management in functional areas. Onsite Services fixed assets, Onsite Services common equipment expense, including rentals, lost productive time, union business, IT, Government Security/Plant protection, non-program specific security and clearances, publications, employment costs/relocation, food services, mail services, training, severance, misc. employment costs, mortgage assistance, learning and development, wellness center/medical services, copiers, vehicle leases, fuel, freight on indirect items, postage, scrap income, food services credits and allocation from the SSC Core Segment U&amp;O Service Total and Fringe Pools.</p> <p style="margin: 0in 0in 0pt;">&nbsp;</p> <p style="margin: 0in 0in 0pt;">Base: Direct labor dollars of the cost centers assigned to the SSC Services Segment Onsite Services Overhead Pool, including all level of effort engineering, operations and maintenance, sustainment performed at onsite facilities, analysis of data obtain from space assets, quality assurance, program planning, material planning, program specific training, procurement, contract administration/C&amp;DM, program management, estimating/contract pricing, human resources business partners assigned to LOBs or programs.</p> <h2 style="margin: 6pt 0in 0pt;"><span style="font-family: ''Times New Roman'',serif;">&nbsp;</span></h2>',0,0,56);
INSERT INTO [dbo].[Section] ([UpdateDate],[RevisionID],[ID],[ParentID],[DisplayOrder],[Title],[SectionContentTypeID],[TextContent],[IsInternalSection],[DisplayRateCode],[RevisionUniqueSectionId]) VALUES (GETDATE(),1,57,55,1,null,3,'',0,0,57);
INSERT INTO [dbo].[Section] ([UpdateDate],[RevisionID],[ID],[ParentID],[DisplayOrder],[Title],[SectionContentTypeID],[TextContent],[IsInternalSection],[DisplayRateCode],[RevisionUniqueSectionId]) VALUES (GETDATE(),1,58,55,2,null,2,'<p>2017-2019 Rates Submitted, Not Negotiated, reference LMSSC-116-008, dated February 1, 2016</p>',0,0,58);
INSERT INTO [dbo].[Section] ([UpdateDate],[RevisionID],[ID],[ParentID],[DisplayOrder],[Title],[SectionContentTypeID],[TextContent],[IsInternalSection],[DisplayRateCode],[RevisionUniqueSectionId]) VALUES (GETDATE(),1,59,13,12,'Onsite Services Overhead',1,'',0,0,59);
INSERT INTO [dbo].[Section] ([UpdateDate],[RevisionID],[ID],[ParentID],[DisplayOrder],[Title],[SectionContentTypeID],[TextContent],[IsInternalSection],[DisplayRateCode],[RevisionUniqueSectionId]) VALUES (GETDATE(),1,60,59,0,null,2,'<p>The Offsite Services includes the indirect costs of cost centers whose efforts are utilized primarily in Services Segment contract performed at non-primary LMSSC facilities.&nbsp; These facilities are generally defined as facilities not owned or provided by Lockheed Martin Corporation Space Systems Company where SSC Services Segment organization are located.&nbsp; Indirect Labor and Non-labor costs included:&nbsp; Lost productive time, union business, allocation form the SSC Core Segment U&amp;O, Services Total and Fringe pools, IT.&nbsp;</p> <p style="margin-bottom: .0001pt;">Base:&nbsp; Direct labor dollars in the Offsite Services Overhead Pool base include the cost centers performing the following:&nbsp; Direct labor dollars of cost centers assigned to the SSC Services Segment Offsite Services Overhead Pool, including all level of effort engineering, operations and maintenance, sustainment performed at offsite facilities, analysis of data obtained from space assets, quality assurance, program planning, material planning, program specific training, procurement, contract administration/C&amp;DM, program management/business management, estimating/contract pricing, Human Resource Business Partners assigned to LOBs or programs.</p>',0,0,60);
INSERT INTO [dbo].[Section] ([UpdateDate],[RevisionID],[ID],[ParentID],[DisplayOrder],[Title],[SectionContentTypeID],[TextContent],[IsInternalSection],[DisplayRateCode],[RevisionUniqueSectionId]) VALUES (GETDATE(),1,61,59,1,null,3,'',0,0,61);
