INSERT INTO [dbo].[Section] ([UpdateDate],[RevisionID],[ID],[ParentID],[DisplayOrder],[Title],[SectionContentTypeID],[TextContent],[IsInternalSection],[DisplayRateCode],[RevisionUniqueSectionId]) VALUES (GETDATE(),1,72,71,0,null,2,'<p>Costs incurred for SSC Core Segment, SSC Services Segment and SSC Home Office employees in the LMOS Benefits structure:&nbsp; Incentive Compensation and Special Recognition Awards (SRA), Retiree Medical, Group insurance, Workers Compensation, Vacations, Holidays, Hourly Sick Leave, Unemployment Insurance, Social Security, Hourly and Salary Pensions, Deferred Compensation, Supplemental Savings Plan and Administrative Fees.</p> <p style="margin-bottom: .0001pt;">Base:&nbsp; Direct labor dollars of the SSC Core Segment, SSC Services Segment and SSC Home Office employees in the LMOS Benefits structure (excludes labor included in fringe benefits and Contract Labor)</p>',0,0,72);
