INSERT INTO [dbo].[Section] ([UpdateDate],[RevisionID],[ID],[ParentID],[DisplayOrder],[Title],[SectionContentTypeID],[TextContent],[IsInternalSection],[DisplayRateCode],[RevisionUniqueSectionId]) VALUES (GETDATE(),1,84,83,0,null,2,'<p style="margin: 0in 0in 0pt;">Gross rates include costs that are unallowable under FAR for billing to the U.S. Government. Gross rates are used for internal financial accounting (QRFs) or pricing commercial effort.</p><p style="margin: 0in 0in 0pt 0.5in; text-align: center;">&nbsp;</p> <p style="margin: 0in 0in 0pt; text-align: center;">FOR USE IN COMMERCIAL/FOREIGN PROPOSALS</p> <p style="margin: 0in 0in 0pt; text-align: center;"><strong>DO NOT USE IN U.S. GOVERNMENT PROPOSALS</strong></p>',0,0,84);
