INSERT INTO [dbo].[Section] ([UpdateDate],[RevisionID],[ID],[ParentID],[DisplayOrder],[Title],[SectionContentTypeID],[TextContent],[IsInternalSection],[DisplayRateCode],[RevisionUniqueSectionId]) VALUES (GETDATE(),1,87,null,2,'LMSSC Labor Costs',1,'',0,0,87);
INSERT INTO [dbo].[Section] ([UpdateDate],[RevisionID],[ID],[ParentID],[DisplayOrder],[Title],[SectionContentTypeID],[TextContent],[IsInternalSection],[DisplayRateCode],[RevisionUniqueSectionId]) VALUES (GETDATE(),1,88,87,0,null,2,'<p style="margin: 0in 0in 0pt;">All labor is charged to contracts based on standard labor rates. The standard rates are based on segment, site, pool and major product line<span style="color: red;">. </span>Heritage Segment identifiers include: XX = Space Programs, FB = Strategic Missiles, MM = Missile Defense. Mission Solutions segment identifiers are: C1 = Core/Tier 1, S1 = Services/Tier 1 and S2 = Services Tier 2. At the end of the month, if payroll is different than LMSSC standard rate costing, a variance is allocated. There are five labor levels for each site/pool.</p> <p style="margin: 0in 0in 0pt;">&nbsp;</p> <p style="margin: 0in 0in 0pt; text-align: justify;"><u><span style="font-size: 11pt;"><span style="text-decoration: none;">&nbsp;</span></span></u></p> <p style="margin: 0in 0in 0pt; text-align: justify;"><strong><u>Salary Grade Levels &ndash; Typical Minimum Education and Experience</u></strong><u>:</u></p> <p style="margin: 0in 0in 0pt; text-align: justify;">&nbsp;</p> <p style="margin: 0in 0in 0pt; text-align: justify;"><strong>A = Technical/Administrative Support (Hourly/NES</strong>) &ndash; High school diploma with additional specialized training or associates degree with 5 years of experience.</p> <p style="margin: 0in 0in 0pt; text-align: justify;">&nbsp;</p> <p style="margin: 0in 0in 0pt; text-align: justify;"><strong>B = Associate/Engineer &ndash; (Salary Grade 1&amp;2)</strong> &ndash; Bachelor&rsquo;s degree in Engineering/Technical or Business from an accredited college in related discipline, with 0 years of experience. Entry Level. Bachelor&rsquo;s degree in Engineering/Technical or Business from an accredited college in related discipline, with 2 years of professional experience or 0 years of experience with related Master&rsquo;s degree. Considered experienced, but still a learner.</p> <p style="margin: 0in 0in 0pt; text-align: justify;">&nbsp;</p> <p style="margin: 0in 0in 0pt; text-align: justify;"><strong>C = Senior &amp; Staff - (Salary Grade 3&amp;4)</strong> &ndash; Bachelor&rsquo;s degree in Engineering/Technical or Business from an accredited college in related discipline, with 5 years of professional experience, or 3 years of related experience with Master&rsquo;s degree. Considered career, or journey level. Bachelor&rsquo;s degree in Engineering/Technical or Business from an accredited college in related discipline, with 9 years of professional experience, or 7 years of related experience with Master&rsquo;s degree. Considered an emerging authority.</p> <p style="margin: 0in 0in 0pt; line-height: normal;"><span style="font-family: ''Times New Roman'',serif; font-size: 12pt;">&nbsp;</span></p> <p style="margin: 0in 0in 0pt; line-height: normal;"><strong><span style="font-family: ''Times New Roman'',serif; font-size: 12pt;">D = Senior Staff - (Salary Grade 5)</span></strong><span style="font-family: ''Times New Roman'',serif; font-size: 12pt;"> &ndash; Bachelor&rsquo;s degree in Engineering/Technical or Business from an accredited college in related discipline, with 14 years of professional experience, or 12 years of related experience with Master&rsquo;s degree. Considered an expert, authority in discipline.</span></p> <p style="margin: 0in 0in 0pt; line-height: normal;"><span style="font-family: ''Times New Roman'',serif; font-size: 12pt;">&nbsp;</span></p> <p style="margin: 0in 0in 0pt; line-height: normal;"><strong><span style="font-family: ''Times New Roman'',serif; font-size: 12pt;">E = Leadership - (Salary Grade 6&amp;Up)</span></strong><span style="font-family: ''Times New Roman'',serif; font-size: 12pt;"> &ndash; Bachelor&rsquo;s degree in Engineering/Technical or Business from an accredited college in related discipline, with 20 years of professional experience, or 18 years with Master&rsquo;s degree, or 15 years with a PhD degree. Viewed as the most senior authority in discipline. </span></p> <p style="margin: 0in 0in 0pt;">&nbsp;</p> <p style="margin: 0in 0in 0pt;">&nbsp;</p>',0,0,88);
INSERT INTO [dbo].[Section] ([UpdateDate],[RevisionID],[ID],[ParentID],[DisplayOrder],[Title],[SectionContentTypeID],[TextContent],[IsInternalSection],[DisplayRateCode],[RevisionUniqueSectionId]) VALUES (GETDATE(),1,89,87,1,'Labor Rates',1,'',0,0,89);
INSERT INTO [dbo].[Section] ([UpdateDate],[RevisionID],[ID],[ParentID],[DisplayOrder],[Title],[SectionContentTypeID],[TextContent],[IsInternalSection],[DisplayRateCode],[RevisionUniqueSectionId]) VALUES (GETDATE(),1,90,89,0,null,2,'<p style="margin: 0in 0in 0pt;"><span style="font-family: ''Times New Roman'',serif; font-size: 12pt;">2017 Core Segment Activity Type Site Labor Rates in this document are derived from total paid dollars divided by the total paid hours for each site, based on January through December 2015 actuals. There are six rates for each site &ndash; A straight time and overtime rate for Level A and one rate for each of the remaining site labor levels (Labor levels B-E).&nbsp;&nbsp; (Escalation rates are applicable to all levels except in level A&rsquo;s where there are union agreements.) </span></p> <p style="margin: 0in 0in 0pt;"><span style="font-family: ''Times New Roman'',serif; font-size: 12pt;">&nbsp;</span></p> <p style="margin: 0in 0in 0pt;"><span style="font-family: ''Times New Roman'',serif; font-size: 12pt;">2017 Services Segment Activity Type Labor Rates are derived from employee actual rates. </span></p> <p style="margin: 0in 0in 0pt;"><span style="font-family: ''Times New Roman'',serif; font-size: 12pt;">&nbsp;</span></p> <p style="margin: 0in 0in 0pt;"><span style="font-family: ''Times New Roman'',serif; font-size: 12pt;">The Submitted/Negotiated rates are used for pricing current and future years only. </span></p> <p style="margin: 0in 0in 0pt;"><span style="font-family: ''Times New Roman'',serif; font-size: 12pt;">&nbsp;</span></p>',0,0,90);
INSERT INTO [dbo].[Section] ([UpdateDate],[RevisionID],[ID],[ParentID],[DisplayOrder],[Title],[SectionContentTypeID],[TextContent],[IsInternalSection],[DisplayRateCode],[RevisionUniqueSectionId]) VALUES (GETDATE(),1,91,87,2,'Composite Rates',1,'',0,0,91);
INSERT INTO [dbo].[Section] ([UpdateDate],[RevisionID],[ID],[ParentID],[DisplayOrder],[Title],[SectionContentTypeID],[TextContent],[IsInternalSection],[DisplayRateCode],[RevisionUniqueSectionId]) VALUES (GETDATE(),1,92,91,0,null,2,'<p style="margin: 0in 0in 0pt;">Use of composite rates must be documented in the proposal. Documentation must include rationale for skill levels and rate calculations derived from submitted/FPRA rates.</p>',0,0,92);
INSERT INTO [dbo].[Section] ([UpdateDate],[RevisionID],[ID],[ParentID],[DisplayOrder],[Title],[SectionContentTypeID],[TextContent],[IsInternalSection],[DisplayRateCode],[RevisionUniqueSectionId]) VALUES (GETDATE(),1,93,87,3,'Prior Year Rates',1,'',0,0,93);
INSERT INTO [dbo].[Section] ([UpdateDate],[RevisionID],[ID],[ParentID],[DisplayOrder],[Title],[SectionContentTypeID],[TextContent],[IsInternalSection],[DisplayRateCode],[RevisionUniqueSectionId]) VALUES (GETDATE(),1,94,93,0,null,2,'<p style="margin: 0in 0in 0pt;">Program history should be used to develop prior year labor rates. <a href="https://space.p.external.lmco.com/sites/fbo/CCDME/trng/Estimating%20SME%20Training/Actuals_Prior%20Year_Instructions.pptx">See training</a>, Actuals_Prior_Year_Instruction. FPR rates should not be used for pricing prior year.</p>',0,0,94);
INSERT INTO [dbo].[Section] ([UpdateDate],[RevisionID],[ID],[ParentID],[DisplayOrder],[Title],[SectionContentTypeID],[TextContent],[IsInternalSection],[DisplayRateCode],[RevisionUniqueSectionId]) VALUES (GETDATE(),1,95,87,4,'Current Year Actuals',1,'',0,0,95);
INSERT INTO [dbo].[Section] ([UpdateDate],[RevisionID],[ID],[ParentID],[DisplayOrder],[Title],[SectionContentTypeID],[TextContent],[IsInternalSection],[DisplayRateCode],[RevisionUniqueSectionId]) VALUES (GETDATE(),1,96,95,0,null,2,'<ul style="list-style-type: disc; direction: ltr;"> <li style="color: black;"><span style="color: black;">FPR submitted or negotiated rates must be used to price current year. </span><span style="color: black; font-family: ''Cambria'',serif;">FPR activity type rates are projected rates for the full-year including planned merit increases and union contract wage adjustments. </span></li> <li style="color: black; font-family: ''Cambria'',serif; font-size: 12pt;"><span style="color: black; font-family: ''Cambria'',serif;">The SAP rate table is loaded only once at the beginning of each LMSSC FY</span></li> <li style="color: black; font-family: ''Cambria'',serif; font-size: 12pt;"><span style="color: black; font-family: ''Cambria'',serif;">Variances to the standard rates are performed monthly on a year-to-date basis</span></li> <li style="color: black; font-family: ''Cambria'',serif; font-size: 12pt;"><span style="color: black; font-family: ''Cambria'',serif;">Forward Pricing Rates (FPR) used in proposals may not match the rates in SAP due to currency of the FPR </span></li> <li style="color: black; font-family: ''Cambria'',serif; font-size: 12pt;"><span style="color: black; font-family: ''Cambria'',serif;">Since variances are monthly on a year-to-date basis, the dollars will continue changing until year-end. </span></li> <li style="color: black; font-family: ''Cambria'',serif; font-size: 12pt;"><strong><span style="color: black; font-family: ''Cambria'',serif;">Note: Even if the only month you have hours in is January, your labor dollars will continue to be adjusted.</span></strong></li> <li style="color: black; font-family: ''Cambria'',serif; font-size: 12pt;"><span style="color: black; font-family: ''Cambria'',serif;">For this reason, pricing will always use the FPR published for that year.</span></li> <li style="color: black; font-family: ''Cambria'',serif; font-size: 12pt;"><span style="color: black; font-family: ''Cambria'',serif;">SAP actuals are only used to price prior year&rsquo;s costs when rates are final for the year.</span></li> </ul>',0,0,96);
INSERT INTO [dbo].[Section] ([UpdateDate],[RevisionID],[ID],[ParentID],[DisplayOrder],[Title],[SectionContentTypeID],[TextContent],[IsInternalSection],[DisplayRateCode],[RevisionUniqueSectionId]) VALUES (GETDATE(),1,97,87,5,'Activity Type Labor Rates',1,'',0,0,97);
INSERT INTO [dbo].[Section] ([UpdateDate],[RevisionID],[ID],[ParentID],[DisplayOrder],[Title],[SectionContentTypeID],[TextContent],[IsInternalSection],[DisplayRateCode],[RevisionUniqueSectionId]) VALUES (GETDATE(),1,98,97,0,null,2,'<p>2017 &ndash; 2020 Heritage Labor Rates, FPRA 16-07 effective July 18, 2016. <br />Labor Rates for years 2021 &amp; On are not covered in the agreement (FPRA). See section 4.0 for Labor Escalation.</p> <p>2017 &ndash;2019 Mission Solutions Labor Rates, FPRA 16-06 Rev.1, dated September 19, 2016. <br />Labor Rates for years 2020 &amp; On are not covered in the agreement (FPRA). See Section 4.0 for Labor Escalation.</p> <p><br /> (Attachments to be added by Central Estimating)</p> <p>&nbsp;</p> <p><em>Excel Version</em></p> <p><em>&nbsp;</em></p> <p><a>https://space.p.external.lmco.com/sites/fbo/CCDME/Estimating/Rates/default.aspx</a></p>',0,0,98);
