INSERT INTO [dbo].[Section] ([UpdateDate],[RevisionID],[ID],[ParentID],[DisplayOrder],[Title],[SectionContentTypeID],[TextContent],[IsInternalSection],[DisplayRateCode],[RevisionUniqueSectionId]) VALUES (GETDATE(),1,100,97,2,null,2,'<p>LMSSC ACTIVITY TYPE LABOR RATES (FPRA 16-07, July 18, 2016)<br />MISSION SOLUTIONS LOB CORE &amp; SERVICES SEGMENT ACTIVITY TYPE RATES (FPRA 16-06 Rev 1, dated September 19, 2016)<br />Escalated 2017 Labor Rates (with variance)</p> <p>Note: The Mission Solutions Level A overtime rates do not include shift premiums. Include these adjustments in proposal pricing when applicable.&nbsp;&nbsp;</p>',0,0,100);
