INSERT INTO [dbo].[Section] ([UpdateDate],[RevisionID],[ID],[ParentID],[DisplayOrder],[Title],[SectionContentTypeID],[TextContent],[IsInternalSection],[DisplayRateCode],[RevisionUniqueSectionId]) VALUES (GETDATE(),1,120,119,0,null,2,'<p style="margin: 0in 0in 0pt;">The Travel Escalation rates provided below are <u>not negotiated</u> but are recommended for use. Justification and data sources are required when using alternative escalation rates.</p> <p style="margin: 0in 0in 0pt;">&nbsp;</p> <p style="margin: 0in 0in 0pt;">Travel escalation is based on a weighted average of the following elements from the IHS Global</p> <p style="margin: 0in 0in 0pt;">Insight, Pricing and Purchasing Service, <span style="color: black;">2nd Quarter 2017.</span></p> <p style="margin: 0in 0in 0pt;"><span style="color: black;">Corporate Expenses, CPI, Airfares; Lodging Away from Home</span>; Restaurant Meals; PPI Passenger Car Rental; Other - CPI, All Items, Urban (Aggregate Price)</p> <p style="margin: 0in 0in 0pt;">&nbsp;</p> <p style="margin: 0in 0in 0pt;">Note: 2017-2019 have been adjusted to remove rental car. The current rental car agreement has a negotiated rate for these years.</p> <p style="margin: 0in 0in 0pt;">&nbsp;</p> <table style="width: 437pt; border-collapse: collapse;"> <tbody> <tr style="height: 12.75pt;"> <td style="background: navy; padding: 0in 5.4pt; border: #000000; width: 53pt; height: 12.75pt;"> <p style="margin: 0in 0in 0pt; text-align: center;"><strong><span style="color: white;">2017</span></strong></p> </td> <td style="background: navy; padding: 0in 5.4pt; border: #000000; width: 56pt; height: 12.75pt;"> <p style="margin: 0in 0in 0pt; text-align: center;"><strong><span style="color: white;">2018</span></strong></p> </td> <td style="background: navy; padding: 0in 5.4pt; border: #000000; width: 62pt; height: 12.75pt;"> <p style="margin: 0in 0in 0pt; text-align: center;"><strong><span style="color: white;">2019</span></strong></p> </td> <td style="background: navy; padding: 0in 5.4pt; border: #000000; width: 53pt; height: 12.75pt;"> <p style="margin: 0in 0in 0pt; text-align: center;"><strong><span style="color: white;">2020</span></strong></p> </td> <td style="background: navy; padding: 0in 5.4pt; border: #000000; width: 58pt; height: 12.75pt;"> <p style="margin: 0in 0in 0pt; text-align: center;"><strong><span style="color: white;">2021</span></strong></p> </td> <td style="background: navy; padding: 0in 5.4pt; border: #000000; width: 53pt; height: 12.75pt;"> <p style="margin: 0in 0in 0pt; text-align: center;"><strong><span style="color: white;">2022</span></strong></p> </td> <td style="background: navy; padding: 0in 5.4pt; border: #000000; width: 50pt; height: 12.75pt;"> <p style="margin: 0in 0in 0pt; text-align: center;"><strong><span style="color: white;">2023</span></strong></p> </td> <td style="background: navy; padding: 0in 5.4pt; border: #000000; width: 52pt; height: 12.75pt;"> <p style="margin: 0in 0in 0pt; text-align: center;"><strong><span style="color: white;">2024</span></strong></p> </td> </tr> <tr style="height: 12.75pt;"> <td style="padding: 0in 5.4pt; border: 1pt solid black; width: 53pt; height: 12.75pt; background-color: transparent;"> <p style="margin: 0in 0in 0pt; text-align: right;"><strong><span style="color: black;">3.23%</span></strong></p> </td> <td style="border-width: 1pt 1pt 1pt 0px; border-style: solid solid solid none; border-color: black black black #000000; padding: 0in 5.4pt; width: 56pt; height: 12.75pt; background-color: transparent;"> <p style="margin: 0in 0in 0pt; text-align: right;"><strong><span style="color: black;">2.46%</span></strong></p> </td> <td style="border-width: 1pt 1pt 1pt 0px; border-style: solid solid solid none; border-color: black black black #000000; padding: 0in 5.4pt; width: 62pt; height: 12.75pt; background-color: transparent;"> <p style="margin: 0in 0in 0pt; text-align: right;"><strong><span style="color: black;">1.94%</span></strong></p> </td> <td style="border-w