INSERT INTO [dbo].[Section] ([UpdateDate],[RevisionID],[ID],[ParentID],[DisplayOrder],[Title],[SectionContentTypeID],[TextContent],[IsInternalSection],[DisplayRateCode],[RevisionUniqueSectionId]) VALUES (GETDATE(),1,145,144,0,null,2,'<p style="margin: 0in 0in 0pt;">SSC labor and non-labor costs incurred for multi-program activity in support of Production personnel. Tasks include, but not limited to management, supervision and technical interface performed by leaders and Production personnel in meeting program requirements, Resource Management, Human Resources, oversight and administrative effort.&nbsp; Process control testing, lab test method development and verification, ESD certification, material management, stock sweeps, methods and area engineering, manufacturing process instruction (MPI) maintenance.&nbsp;&nbsp; Includes pagers, cell phones, and other comparable communications devices; travel expense incurred supporting multi-program requirements and related coordination, status and reporting efforts.&nbsp; Effort excludes support of FBM manufacturing cost centers and remote sites.&nbsp; Production web server technical information integration, depreciation, and maintenance to support multi-program compliance.&nbsp; EBS system administration and user support cost allocations.</p> <p style="margin: 0in 0in 0pt;">&nbsp;</p> <p style="margin: 0in 0in 0pt; tab-stops: -.5in;"><span style="font-family: ''Times New Roman'',serif; font-size: 12pt;">Base = Direct labor hours in Manufacturing Touch Sending Cost Centers in the Production Overhead Pool excluding Fleet Ballistic Missile (FBM) Manufacturing Touch Sending Cost Centers</span></p> <p style="margin: 0in 0in 0pt; tab-stops: -.5in;"><span style="font-family: ''Times New Roman'',serif; font-size: 12pt;">Result = Labor cost in Production Pool</span> <span style="font-family: ''Times New Roman'',serif; font-size: 12pt;">and ODC dollars</span></p> <p style="margin: 0in 0in 0pt; tab-stops: -.5in;">&nbsp;</p> <table sty