INSERT INTO [dbo].[Section] ([UpdateDate],[RevisionID],[ID],[ParentID],[DisplayOrder],[Title],[SectionContentTypeID],[TextContent],[IsInternalSection],[DisplayRateCode],[RevisionUniqueSectionId]) VALUES (GETDATE(),1,155,154,0,null,2,'<p style="margin: 0in 0in 0pt;">SSC Labor and non-labor costs incurred for multi-program management interface, resource deployment, oversight and administrative effort in support of Assembly, Test and Launch Operations personnel. Includes management and technical effort in meeting program requirements. Scope of effort includes but is not limited to: mechanical and electrical test engineering, test procedures and software, test operations, logistics, launch operations, MAGE/EAGE, EAGE software, maintenance and calibration of direct acquired equipment, material control, tool control, planning, configuration control, quality control, facility management of chambers and high-bays, material control, shipping and receiving, transportation, resource management and administration. Includes pagers, cell phones, and other comparable communications devices; travel expense incurred supporting multi-program requirements and related coordination, status and reporting efforts; depreciation, maintenance and repair for fixed asset tooling and equipment accountable to the Assembly, Test and Launch Operations Service Center.</p> <p style="margin: 0in 0in 0pt;">&nbsp;</p> <p style="margin: 0in 0in 0pt;">&nbsp;</p> <p style="margin: 0in 0in 0pt; tab-stops: -.5in 0in .5in 1.0in;">Base = Direct labor hours in ATLO Sending Cost Centers in the Development Overhead Pool (Core Segment)</p> <p style="margin: 0in 0in 0pt; tab-stops: -.5in;"><span style="font-family: ''Times New Roman'',serif; font-size: 12pt;">Result = Labor cost in Development Pool</span> <span style="font-family: ''Times New Roman'',serif; font-size: 12pt;">and ODC dollars</span></p> <p style="margin: 0in 0in 0pt; tab-stops: -.5in;">&nbsp;</p> <table style="margin: auto auto auto 5.9pt; width: 28