INSERT INTO [dbo].[Section] ([UpdateDate],[RevisionID],[ID],[ParentID],[DisplayOrder],[Title],[SectionContentTypeID],[TextContent],[IsInternalSection],[DisplayRateCode],[RevisionUniqueSectionId]) VALUES (GETDATE(),1,159,158,0,null,2,'<p style="tab-stops: -.5in 0in .5in 1.0in;">Reproduction labor and consumable materials and supplied expended in the production of various types of hardcopy and softcopy media.</p> <p>&nbsp;</p> <p style="tab-stops: -.5in 0in .5in 1.0in;">Dollars are allocated to direct WBS accounts and overhead cost centers on a year-to-date average expense rate basis for volume and type of service requested.</p> <p style="text-autospace: none;">&nbsp;</p> <p style="text-autospace: none;">This ODC cost must be estimated based on your actual contract allocation - Proposed as a factor.&nbsp; Rates are not published by program.</p>',0,0,159);
