INSERT INTO [dbo].[Section] ([UpdateDate],[RevisionID],[ID],[ParentID],[DisplayOrder],[Title],[SectionContentTypeID],[TextContent],[IsInternalSection],[DisplayRateCode],[RevisionUniqueSectionId]) VALUES (GETDATE(),1,237,236,0,null,2,'<p style="margin: 0in 0in 0pt; tab-stops: 0in .5in 1.0in;">Computing services (<em>administrative, batch, and/or interactive</em>) for each of the following systems:</p> <ol style="list-style-type: decimal; direction: ltr;"> <li style="color: #000000;">Business (Cost Center 5422BC)</li> <li style="color: #000000; font-family: ''Times New Roman'',serif; font-size: 12pt;">Virtual Machine (Cost Center 5422VM)</li> <li style="color: #000000; font-family: ''Times New Roman'',serif; font-size: 12pt;">VAX (Cost Center 5122VA)&nbsp;</li> <li style="color: #000000; font-family: ''Times New Roman'',serif; font-size: 12pt; margin-top: 0in; margin-bottom: 0pt;">The base for application of the rates is computer units. Shared Computer Service Center Rates are not included in the current FPRA. Any computing service costs related to these systems should be proposed as a factor.</li> <li style="color: #000000; font-family: ''Times New Roman'',serif; font-size: 12pt; margin-top: 0in; margin-bottom: 0pt; tab-stops: 0in .5in 1.0in;">SSC direct labor travel costs, equipment, gain or loss on disposal of the equipment, software (including internally developed software and amortization of capitalized software), data processing supplies, vendor computing costs, inter-company work transfers from Lockheed Martin Enterprise Business Systems (EBS), and distributed computing &amp; telecommunications and data center services charges from EBS. This Service Center cost is allocated to only SSC, Sunnyvale Service Centers that incur EBS labor hours.</li> </ol>',0,0,237);
