INSERT INTO [dbo].[Section] ([UpdateDate],[RevisionID],[ID],[ParentID],[DisplayOrder],[Title],[SectionContentTypeID],[TextContent],[IsInternalSection],[DisplayRateCode],[RevisionUniqueSectionId]) VALUES (GETDATE(),1,244,242,1,'Restriction on Disclosure and Use of Data',1,'',0,0,244);
INSERT INTO [dbo].[Section] ([UpdateDate],[RevisionID],[ID],[ParentID],[DisplayOrder],[Title],[SectionContentTypeID],[TextContent],[IsInternalSection],[DisplayRateCode],[RevisionUniqueSectionId]) VALUES (GETDATE(),1,245,244,0,null,2,'<p style="margin: 0in 0in 0pt 27pt;"><em><span style="color: black;">The following paragraphs will be included on the title page of the proposal.</span></em></p> <p style="margin: 0in 0in 0pt 27pt;"><em><span style="color: black;">&nbsp;</span></em></p> <p style="margin: 0in 0in 0pt 27pt; text-indent: -1in;"><span style="color: black; text-transform: uppercase;">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;<u>Restriction on disclosure and use of data</u></span><span style="color: black;">: This proposal or quotation includes data that shall not be disclosed outside the Government and shall not be duplicated, used, or disclosed - in whole or in part - for any purpose other than to evaluate this proposal or quotation. However, if a contract is awarded to this offeror or quoter as a result of - or in connection with - the submission of data, the Government shall have the right to duplicate, use, or disclose the data to the extent provided in the resulting contract. This restriction does not limit the Government''s right to use information contained in data if it is obtained from another source without restriction. The data subject to this restriction are contained in all the sheets of this document. </span></p> <p style="margin: 0in 0in 0pt 27pt; text-indent: -1in;"><span style="color: black;">&nbsp;</span></p> <p style="margin: 0in 0in 0pt 27pt;"><span style="color: black;">This data is further deemed by Lockheed Martin Corporation to contain Trade Secrets and Commercial or Financial information that is privileged and confidential under the Freedom of Information Act (5 U.S.C. 552) and other</span> statutes<span style="color: black;"> prohibiting disclosure (E.G., 18 U.S.C. 1905). </span></p> <p style="margin: 0in 0in 0pt 27pt; text-indent: -1in;"><span style="color: black;">&nbsp;</span></p> <p style="margin: 0in 0in 0pt 27pt;"><em><span style="color: black;">Mark all pages of the proposal with the following disclosure information: </span></em></p> <p style="margin: 0in 0in 0pt 27pt;"><em><span style="color: black;">&nbsp;</span></em></p> <p style="margin: 0in 0in 0pt 27pt;">Lockheed Martin Proprietary Information - Use or disclosure of data contained on this sheet is subject to the restriction on the title page of this proposal/document.</p>',0,0,245);
INSERT INTO [dbo].[Section] ([UpdateDate],[RevisionID],[ID],[ParentID],[DisplayOrder],[Title],[SectionContentTypeID],[TextContent],[IsInternalSection],[DisplayRateCode],[RevisionUniqueSectionId]) VALUES (GETDATE(),1,246,242,2,'LMSSC Forward Pricing Rate Coverage Period',1,'',0,0,246);
INSERT INTO [dbo].[Section] ([UpdateDate],[RevisionID],[ID],[ParentID],[DisplayOrder],[Title],[SectionContentTypeID],[TextContent],[IsInternalSection],[DisplayRateCode],[RevisionUniqueSectionId]) VALUES (GETDATE(),1,247,246,0,null,2,'<p style="margin: 0in 0in 0pt;">In accordance with the Federal Acquisition Regulation and supplements, LMSSC maintains a current forward pricing rate proposal and/or forward pricing rate agreement (together, the &ldquo;FPR&rdquo;). The FPR incorporates all known internal planning assumptions, business base, and cost estimated forecast, inclusive of known risks and opportunities.</p> <p style="margin: 0in 0in 0pt;">&nbsp;</p> <p style="margin: 0in 0in 0pt;">The FPR covers a period of approximately five years, or other reasonable duration as evaluated by LMSSC and the Divisional Administrative Contracting Officer (the &ldquo;Period&rdquo;). The FPR Period is consistent with the United States Government&rsquo;s Future Years Defense Program (&ldquo;FYDP&rdquo;), which plans defense resource allocations in accordance with a five year forecast. The FYDP is one element that LMSSC uses for internal planning; therefore, anything beyond the five year forecast lacks the fidelity provided by analysis of this key element.</p> <p style="margin: 0in 0in 0pt;">&nbsp;</p> <p style="margin: 0in 0in 0pt;">LMSSC&rsquo;s internal planning assumptions are subject to change based on factors including but not limited to the FYDP and new business wins and losses, which may affect the duration of the FPR Period. Although forecasting beyond the FPR Period is impractical, LMSSC conducts frequent, robust reviews of FPR data with the Defense Contract Management Agency to ensure transparency with respect to our planning assumptions and risks and opportunities that could affect the FPR and future years.</p> <p style="margin: 0in 0in 0pt; tab-stops: 183.75pt;">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;</p> <p><span style="font-family: ''Times New Roman'',serif; font-size: 12pt;">Scope beyond the FPR Period is proposed at the FPR Period&rsquo;s final year rates. This consistency is predicated on LMSSC&rsquo;s assumption of a similar future business environment, no known risks or opportunities that would cause a rate change, and a lack of fidelity for forecasting beyond the Period</span></p>',0,0,247);
INSERT INTO [dbo].[Section] ([UpdateDate],[RevisionID],[ID],[ParentID],[DisplayOrder],[Title],[SectionContentTypeID],[TextContent],[IsInternalSection],[DisplayRateCode],[RevisionUniqueSectionId]) VALUES (GETDATE(),1,248,242,3,'Forward Pricing Rate Disclosure – include in proposals',1,'',0,0,248);
INSERT INTO [dbo].[Section] ([UpdateDate],[RevisionID],[ID],[ParentID],[DisplayOrder],[Title],[SectionContentTypeID],[TextContent],[IsInternalSection],[DisplayRateCode],[RevisionUniqueSectionId]) VALUES (GETDATE(),1,249,248,0,null,2,'<p style="margin: 0in 0in 0pt 0.5in;">The following forward pricing rate activities are currently underway between LMSSC and DCMA:</p> <ol style="list-style-type: decimal; direction: ltr;"> <li style="color: #000000;"><span style="font-family: ''Times New Roman'',serif; font-size: 12pt;">Core Segment Indirect &ndash; fact-finding and associated analysis for the extension of a) indirect rates through 2021 and b) update of Huntsville indirect rates from 2017 &ndash; 2021.</span></li> <li style="color: #000000; font-family: ''Times New Roman'',serif; font-size: 12pt;"><span style="font-family: ''Times New Roman'',serif; font-size: 12pt;">Services Segment Indirect &ndash; fact-finding and associated analysis in preparation for an FPRA negotiation (2017-2021). </span></li> <li style="color: #000000; font-family: ''Times New Roman'',serif; font-size: 12pt;"><span style="font-family: ''Times New Roman'',serif; font-size: 12pt;">Direct Labor Rates &ndash; annual labor rate update submitted to DCMA on May 1, 2017. Fact-finding and associated analysis are ongoing.</span></li> </ol> <p style="margin: 0in 0in 0pt 1in;">&nbsp;</p> <p style="margin: 0in 0in 0pt 0.5in; text-align: justify;">LMSSC will continue to utilize the current FPRP or FPRA (listed below) until a new or revised Forward Pricing Rate Agreement is complete and final, or one of the parties notifies the other, in accordance with the terms of the existing FPRA, of its intent to cancel the agreement.&nbsp;</p> <ol style="list-style-type: decimal; direction: ltr;"> <li style="color: #000000;"><span style="font-family: ''Times New Roman'',serif; font-size: 12pt;">Core Segment Indirect Forward Pricing Rate Agreement (FPRA) dated July 8, 2016</span></li> <li style="color: #000000; font-family: ''Times New Roman'',serif; font-size: 12pt;"><span style="font-family: ''Times New Roman'',serif; font-size: 12pt;">Services Segment Indirect Forward Pricing Rate Proposal (FPRP) dated Feb 1, 2016</span></li> <li style="color: #000000; font-family: ''Times New Roman'',serif; font-size: 12pt;"><span style="font-family: ''Times New Roman'',serif; font-size: 12pt;">Direct Labor Rates (FPRA) dated July 18, 2016 for Heritage/Core Segment.</span></li> <li style="color: #000000; font-family: ''Times New Roman'',serif; font-size: 12pt;"><span style="font-family: ''Times New Roman'',serif; font-size: 12pt;">Direct Labor Rates (FPRA) dated September 19, 2016 for Mission Solutions</span></li> <li style="color: #000000; font-family: Times New Roman; font-size: 12pt; margin-top: 1em; margin-bottom: 1em;"><span style="font-family: ''Times New Roman'',serif; font-size: 12pt;">&nbsp;</span></li> </ol> <p style="margin: 0in 0in 0pt 0.5in;">For additional information contact Cindy Russ (DCMA) at 303-977-9885 for the Core Segment and Brandon Boisvert (DCMA) at 303-971-1095 for the Services Segment.</p>',0,0,249);
INSERT INTO [dbo].[Section] ([UpdateDate],[RevisionID],[ID],[ParentID],[DisplayOrder],[Title],[SectionContentTypeID],[TextContent],[IsInternalSection],[DisplayRateCode],[RevisionUniqueSectionId]) VALUES (GETDATE(),1,250,242,4,'Disclosures at Negotiations',1,'',0,0,250);
INSERT INTO [dbo].[Section] ([UpdateDate],[RevisionID],[ID],[ParentID],[DisplayOrder],[Title],[SectionContentTypeID],[TextContent],[IsInternalSection],[DisplayRateCode],[RevisionUniqueSectionId]) VALUES (GETDATE(),1,251,250,0,null,2,'<p style="margin: 0in 0in 0pt 0.5in;">Services Segment: LMSSC is pricing with rates submitted on February 1, 2016 for the Services Segment indirect pools (overhead, G&amp;A, fringe). A recent analysis of those rates as we prepare to negotiate a new FPRA with the DCMA indicates that the negotiated rates will likely be lower than the rates submitted in 2016. If you are in process of or preparing for negotiations of a proposal which includes Services Segment costs, you should disclose this situation to your customer. If the customer wants additional information, they should contact Brandon Boisvert of the Denver DCMA office at 303-971-1095</p> <p style="margin: 0in 0in 0pt 0.5in;">&nbsp;</p> <p style="margin: 0in 0in 0pt 0.5in;">Huntsville Indirect Rates (Core Segment):&nbsp; LMSSC is pricing using the Core Segment indirect FPRA, dated July 8, 2016. A recent analysis, as we prepare to update the FPRA, indicates that the Huntsville rates will likely be higher than those in the current FPRA. If you are in process of or preparing for negotiations of a proposal which includes Huntsville costs, you should disclose this situation to your customer. If the customer wants additional information, they should contact Cindy Russ of the Denver DCMA office at 303-977-9885.</p>',0,0,251);
INSERT INTO [dbo].[Section] ([UpdateDate],[RevisionID],[ID],[ParentID],[DisplayOrder],[Title],[SectionContentTypeID],[TextContent],[IsInternalSection],[DisplayRateCode],[RevisionUniqueSectionId]) VALUES (GETDATE(),1,252,242,5,'Fleet Ballistic Missile Announcement',1,'',0,0,252);
INSERT INTO [dbo].[Section] ([UpdateDate],[RevisionID],[ID],[ParentID],[DisplayOrder],[Title],[SectionContentTypeID],[TextContent],[IsInternalSection],[DisplayRateCode],[RevisionUniqueSectionId]) VALUES (GETDATE(),1,253,252,0,null,2,'<p><span style="font-family: ''Times New Roman'',serif; font-size: 12pt;">On February 23, 2017, Lockheed Martin Space Systems announced plans to relocate over the next eight years the Fleet Ballistic Missile (FBM) program from Sunnyvale, California, to Florida and Colorado.&nbsp; We expect the majority of the relocations to occur in the 2019&ndash;2020 time frame, with some as early as 2018. An analysis of the impact to costs, allocations and materiality will be performed and any updates to Forward Pricing Rate Proposals/Agreements (FPRP/FPRA), if needed, and any disclosures under the Truthful Cost or Pricing Data Act (formerly TINA) will be made as required.</span></p>',0,0,253);
INSERT INTO [dbo].[Section] ([UpdateDate],[RevisionID],[ID],[ParentID],[DisplayOrder],[Title],[SectionContentTypeID],[TextContent],[IsInternalSection],[DisplayRateCode],[RevisionUniqueSectionId]) VALUES (GETDATE(),1,254,null,7,'Cost or Pricing Proposal Disclosures',1,'',0,0,254);
INSERT INTO [dbo].[Section] ([UpdateDate],[RevisionID],[ID],[ParentID],[DisplayOrder],[Title],[SectionContentTypeID],[TextContent],[IsInternalSection],[DisplayRateCode],[RevisionUniqueSectionId]) VALUES (GETDATE(),1,255,254,0,null,2,'<p><span style="font-family: ''Times New Roman'',serif; font-size: 12pt;">All cost or pricing proposals require the following: </span></p>',0,0,255);
INSERT INTO [dbo].[Section] ([UpdateDate],[RevisionID],[ID],[ParentID],[DisplayOrder],[Title],[SectionContentTypeID],[TextContent],[IsInternalSection],[DisplayRateCode],[RevisionUniqueSectionId]) VALUES (GETDATE(),1,256,254,1,'Rates and Factors Tracking Data Disclosure',1,'',0,0,256);
INSERT INTO [dbo].[Section] ([UpdateDate],[RevisionID],[ID],[ParentID],[DisplayOrder],[Title],[SectionContentTypeID],[TextContent],[IsInternalSection],[DisplayRateCode],[RevisionUniqueSectionId]) VALUES (GETDATE(),1,257,256,0,null,2,'<p style="margin: 0in 0in 0pt 27pt; tab-stops: 27.0pt;"><span style="color: black;">Monthly or quarterly actuals are submitted to the Divisional Administrative Contracting Officer (DACO/ACO) for the following forward pricing rates: </span></p> <ul> <li style="margin: 0in 0in 0pt 27pt; tab-stops: 27.0pt .75in;"><span style="color: black;"> Overhead Rates </span></li> <li style="margin: 0in 0in 0pt 27pt; tab-stops: 27.0pt .75in;"><span style="color: black;"> Fringe Benefits</span></li> <li style="margin: 0in 0in 0pt 27pt; tab-stops: 27.0pt .75in;"><span style="color: black;"> G&amp;A</span></li> <li style="margin: 0in 0in 0pt 27pt; tab-stops: 27.0pt .75in;"><span style="color: black;"> Service Center Rates</span></li> <li style="margin: 0in 0in 0pt; tab-stops: 27.0pt .75in;"><span style="color: black;"> Labor Rates</span></li> </ul> <p style="margin: 0in 0in 0pt 27pt; tab-stops: -.5in 27.0pt;"><span style="color: black; font-family: ''Times New Roman'',serif; font-size: 12pt;">&nbsp;</span></p> <p style="margin: 0in 0in 0pt 27pt; tab-stops: -.5in 27.0pt;"><span style="color: black; font-family: ''Times New Roman'',serif; font-size: 12pt;">Monthly or quarterly actuals are disclosed on these rates to the DACO/ACO in accordance with FAR 15.407.3. Since all rates used in this proposal are based upon the latest submittals and as the DACO/ACO has been designated as the official of the Government to negotiate all forward pricing rates with Space Systems, it is recommended that the PCO negotiating this procurement contact the DACO/ACO for any information and impacts due to the most current disclosure.</span></p>',0,0,257);
INSERT INTO [dbo].[Section] ([UpdateDate],[RevisionID],[ID],[ParentID],[DisplayOrder],[Title],[SectionContentTypeID],[TextContent],[IsInternalSection],[DisplayRateCode],[RevisionUniqueSectionId]) VALUES (GETDATE(),1,258,254,2,'Rounding Disclosures',1,'',0,0,258);
INSERT INTO [dbo].[Section] ([UpdateDate],[RevisionID],[ID],[ParentID],[DisplayOrder],[Title],[SectionContentTypeID],[TextContent],[IsInternalSection],[DisplayRateCode],[RevisionUniqueSectionId]) VALUES (GETDATE(),1,259,258,0,null,2,'<p style="margin: 0in 0in 0pt 27pt;"><strong><span style="font-size: 12pt;">ProPricer Pricing Program Rounding Disclosure</span></strong><strong><span style="font-family: ''Times New Roman'',serif; font-size: 12pt;">:</span></strong></p> <p style="margin: 0in 0in 0pt 27pt;"><strong><span style="font-family: ''Times New Roman'',serif; font-size: 12pt;">&nbsp;</span></strong></p> <p style="margin: 0in 0in 0pt 27pt;"><span style="font-family: ''Times New Roman'',serif; font-size: 12pt;">ProPricer is the pricing system for Space Systems. This &ldquo;next generation&rdquo; system is very different than its predecessor and has a very different rounding approach. Hour and dollar values are discretely entered into ProPricer to the nearest whole number but fractional hours and dollars may be created via the application of rates and factors.</span></p> <p style="margin: 0in 0in 0pt 27pt;"><span style="font-family: ''Times New Roman'',serif; font-size: 12pt;">ProPricer generates all &ldquo;priced&rdquo; values to their decimal equivalent and generates reports by aggregating these &ldquo;priced&rdquo; values into total values that are then displayed &ndash; rounded &ndash; to the nearest whole number integer value for both hours and dollars. Labor rates are calculated and applied to the nearest penny but on some summaries the labor rate may appear different due to the rate being applied to an hourly value with a fractional component and the hours and dollars then both being rounded for display. The rate will be correct on the report (and will tie to the labor rate summary reports) but manually applying the math of dividing the rounded dollars by the rounded hours may produce a labor rate that is different. Should you have any questions ask the estimator for a Microsoft Excel download of the report and you will be able to see any fractional components. </span></p>',0,0,259);
INSERT INTO [dbo].[Section] ([UpdateDate],[RevisionID],[ID],[ParentID],[DisplayOrder],[Title],[SectionContentTypeID],[TextContent],[IsInternalSection],[DisplayRateCode],[RevisionUniqueSectionId]) VALUES (GETDATE(),1,260,254,3,'Continuous Improvement Assessments',1,'',0,0,260);
INSERT INTO [dbo].[Section] ([UpdateDate],[RevisionID],[ID],[ParentID],[DisplayOrder],[Title],[SectionContentTypeID],[TextContent],[IsInternalSection],[DisplayRateCode],[RevisionUniqueSectionId]) VALUES (GETDATE(),1,261,260,0,null,2,'<p style="margin: 6pt 0in 0pt 27pt; tab-stops: center 27.0pt left .5in 1.0in 1.5in;">As part of our continuous improvement initiatives, management frequently performs assessments regarding the current cost of doing business. These assessments are accomplished by various means including independent/off-project reviews with project participation included as required. Subjects that <em>may be addressed as part of this effort are potential efficiencies for improving operations through consolidations, cost savings suggestions, alternative approaches and performance challenges. The resultant financial data associated with this effort are not point estimates but are considered preliminary information</em> for initial review and possible further exploration. In the event proposed improvements are then determined to be achievable and accordingly are approved for implementation, notification will be provided of the action commensurate with reconciliation of proposal estimates/program budgets, as applicable.</p>',0,0,261);
INSERT INTO [dbo].[Section] ([UpdateDate],[RevisionID],[ID],[ParentID],[DisplayOrder],[Title],[SectionContentTypeID],[TextContent],[IsInternalSection],[DisplayRateCode],[RevisionUniqueSectionId]) VALUES (GETDATE(),1,262,254,4,'Lockheed Martin Corporation Announcements Regarding the Launch of Destination Wellbeing',1,'',0,0,262);
INSERT INTO [dbo].[Section] ([UpdateDate],[RevisionID],[ID],[ParentID],[DisplayOrder],[Title],[SectionContentTypeID],[TextContent],[IsInternalSection],[DisplayRateCode],[RevisionUniqueSectionId]) VALUES (GETDATE(),1,263,262,0,null,2,'<p><span style="color: black; font-family: ''Times New Roman'',serif; font-size: 12pt;">On August 14, 2017 Lockheed Martin Corporation (LMC) publicly announced revisions to the LMC benefits and compensation plan. As a result of these revisions, an analysis of the impact to costs, allocations and <strong>materiality</strong> will be performed. &nbsp;Any resulting impact to Forward Pricing Rate Proposals/Agreements (FPRP/FPRA), and disclosures under the Truthful Cost or Pricing Data Statute (formerly TINA) will be made as required.</span></p>',0,0,263);
INSERT INTO [dbo].[Section] ([UpdateDate],[RevisionID],[ID],[ParentID],[DisplayOrder],[Title],[SectionContentTypeID],[TextContent],[IsInternalSection],[DisplayRateCode],[RevisionUniqueSectionId]) VALUES (GETDATE(),1,264,254,5,'Lockheed Martin Space Systems Business Changes',1,'',0,0,264);
INSERT INTO [dbo].[Section] ([UpdateDate],[RevisionID],[ID],[ParentID],[DisplayOrder],[Title],[SectionContentTypeID],[TextContent],[IsInternalSection],[DisplayRateCode],[RevisionUniqueSectionId]) VALUES (GETDATE(),1,265,264,0,null,2,'<p style="margin: 0in 0in 0pt 0.5in;"><span style="color: red;">Lockheed Martin Space Systems is currently assessing cost, allocation and materiality impacts for the following business changes:</span></p> <ul> <li style="margin: 0in 0in 0pt 0.75in; text-indent: -0.25in;"><span style="color: red;">Destination Wellbeing</span></li> <li style="margin: 0in 0in 0pt 0.75in; text-indent: -0.25in;"><span style="color: red;">SSC new business forecast</span></li> <li style="margin: 0in 0in 0pt 0.75in; text-indent: -0.25in;"><span style="color: red;">Orion personnel movement from the Services Segment to Core Segment</span></li> </ul> <p style="margin: 0in 0in 0pt 0.75in;"><span style="color: red;">&nbsp;</span></p> <p style="margin: 0in 0in 0pt 0.5in;"><span style="color: red;">Updates to Forward Pricing Rate Proposals/Agreements (FPRP/FPRA) will be made, as needed.&nbsp; Any disclosures under the Truthful Cost or Pricing Data Act (formerly TINA) will be made as required.</span></p>',0,0,265);
INSERT INTO [dbo].[Section] ([UpdateDate],[RevisionID],[ID],[ParentID],[DisplayOrder],[Title],[SectionContentTypeID],[TextContent],[IsInternalSection],[DisplayRateCode],[RevisionUniqueSectionId]) VALUES (GETDATE(),1,266,null,8,'Disclosures required only if applicable',1,'',0,0,266);
INSERT INTO [dbo].[Section] ([UpdateDate],[RevisionID],[ID],[ParentID],[DisplayOrder],[Title],[SectionContentTypeID],[TextContent],[IsInternalSection],[DisplayRateCode],[RevisionUniqueSectionId]) VALUES (GETDATE(),1,267,266,0,null,2,'<p style="margin: 0in 0in 0pt 31.5pt; border: currentColor;"><span style="font-family: ''Times'',serif;">Please review and include the appropriate disclosures.</span></p>',0,0,267);
INSERT INTO [dbo].[Section] ([UpdateDate],[RevisionID],[ID],[ParentID],[DisplayOrder],[Title],[SectionContentTypeID],[TextContent],[IsInternalSection],[DisplayRateCode],[RevisionUniqueSectionId]) VALUES (GETDATE(),1,268,266,1,'Enterprise Business Systems (EBS) - Sole Source Justification Disclosure',1,'',0,0,268);
INSERT INTO [dbo].[Section] ([UpdateDate],[RevisionID],[ID],[ParentID],[DisplayOrder],[Title],[SectionContentTypeID],[TextContent],[IsInternalSection],[DisplayRateCode],[RevisionUniqueSectionId]) VALUES (GETDATE(),1,269,268,0,null,2,'<p style="margin: 0in 0in 0pt 0.5in;">DIRECTIONS: The following proposal boilerplate pertains to the sole source justification for the practice of using LM EBS for services. This disclosure will be included in all proposals in which LM EBS is the sole source for technical computer services.</p> <p style="margin: 0in 0in 0pt; text-indent: 0.5in;">Sole Source Justification, LM EBS Disclosure</p> <p style="margin: 0in 40.5pt 0pt 0.5in;">DoD FAR Supplement C-207.2, Intra-Company Transactions, speaks to the policy of competing affiliates and divisions with outside subcontractors. Giving preference to affiliates is not necessarily undesirable, but only so when policies evolve into unacceptable practices. The regulations do not require Lockheed Martin to either consider a competitive procurement of hardware, software, and services, or to prepare a sole source justification for the use of LM EBS. Use of LM EBS is permitted by regulation and standard procedure. FAR 31.205-26, Material Costs, establishes the guideline that materials, supplies, and services sold or transferred between divisions or affiliates shall be on the basis of costs incurred.</p>',0,0,269);
INSERT INTO [dbo].[Section] ([UpdateDate],[RevisionID],[ID],[ParentID],[DisplayOrder],[Title],[SectionContentTypeID],[TextContent],[IsInternalSection],[DisplayRateCode],[RevisionUniqueSectionId]) VALUES (GETDATE(),1,270,266,2,'Service Center Disclosure',1,'',0,0,270);
INSERT INTO [dbo].[Section] ([UpdateDate],[RevisionID],[ID],[ParentID],[DisplayOrder],[Title],[SectionContentTypeID],[TextContent],[IsInternalSection],[DisplayRateCode],[RevisionUniqueSectionId]) VALUES (GETDATE(),1,271,270,0,null,2,'<p><span style="font-family: ''Times New Roman'',serif; font-size: 12pt;">The overhead pools assigned to the labor costs of various Service Centers noted in the results of the rates are based upon the overhead pools of the organizations which normally charge to the Service Centers. These assignments are shown for the convenience of those pricing and budgeting proposals. However, the actual allocations of Service Center charges may result in labor and overhead costs from other overhead pools because SAP keeps the accounting attributes (overhead pool of charging organization) of charges to Service Centers intact through the entire allocation process. This means that overhead rates applied to Service Center direct labor costs are determined by the organizations which charged into the Service Center during each calendar year, not by the organization hours which forms the base for the Service Center allocation.</span></p>',0,0,271);
INSERT INTO [dbo].[Section] ([UpdateDate],[RevisionID],[ID],[ParentID],[DisplayOrder],[Title],[SectionContentTypeID],[TextContent],[IsInternalSection],[DisplayRateCode],[RevisionUniqueSectionId]) VALUES (GETDATE(),1,272,266,3,'Accounting Data Report (formerly SADE)',1,'',0,0,272);
INSERT INTO [dbo].[Section] ([UpdateDate],[RevisionID],[ID],[ParentID],[DisplayOrder],[Title],[SectionContentTypeID],[TextContent],[IsInternalSection],[DisplayRateCode],[RevisionUniqueSectionId]) VALUES (GETDATE(),1,273,272,0,null,2,'<p><span style="font-family: ''Times New Roman'',serif; font-size: 12pt;">ADR (Accounting Data Report) is a data warehouse of SAP actual accounting information (Monthly, Weekly, &amp; other) that allows the analyst to custom define and generate reports based on their individual needs. This historical data is easily extracted for proposal preparation/BOE generation, Cost Management analysis, and trend analysis. </span></p>',0,0,273);
INSERT INTO [dbo].[Section] ([UpdateDate],[RevisionID],[ID],[ParentID],[DisplayOrder],[Title],[SectionContentTypeID],[TextContent],[IsInternalSection],[DisplayRateCode],[RevisionUniqueSectionId]) VALUES (GETDATE(),1,274,266,4,'Program Product Sourcing Process',1,'',0,0,274);
INSERT INTO [dbo].[Section] ([UpdateDate],[RevisionID],[ID],[ParentID],[DisplayOrder],[Title],[SectionContentTypeID],[TextContent],[IsInternalSection],[DisplayRateCode],[RevisionUniqueSectionId]) VALUES (GETDATE(),1,275,274,0,null,2,'<p style="margin: 6pt 0in 0pt 27pt; tab-stops: center 27.0pt left .5in 1.0in 1.5in;">The Lockheed Martin Space Systems Company (LMSSC) Program Product Sourcing process, documented in CIPS N2.1.1-T1-PgmMgt-2.0, requires program hardware and software requirements, as documented by the program-specific PMHSL (Program Master Hardware Software List), to be compared with the Corporate Strategic Products and Services List and the LMSSC Strategic Make/Buy list to determine which items require a Formal Make Buy Analysis (FMBA). The FMBA must illustrate that sound business and technical judgments were applied to each major element of the program&rsquo;s product sourcing decisions, and that the technical, business, quality and cost decision criteria are supported by sufficient backup data and explanations so that the rationale for each make or buy analysis decision is apparent. Should the program-specific PMHSL indicate a sourcing preference that is not in accordance with the Corporate Strategic Products and Services List and the LMSSC Strategic Make/Buy list, a detailed Make/Buy Trade Analysis must be performed. This analysis is to include cost, technical, schedule and risk evaluations, and include a best value trade/evaluation of product data considering all program performance requirements (cost, technical, schedule, core competencies, critical skills retention, direct base, rates including overhead rate impacts, and risk).</p> <p style="margin: 6pt 0in 0pt 27pt; tab-stops: center 27.0pt left .5in 1.0in 1.5in;">LMSSC typically prices inter-organizational work transfers at cost. FAR 15.404-3b requirements for conducting cost or price analysis are not applicable to inter-organizational work transfers. Instead, FAR 15.408 Table 15-2 IIA (2) requires a separate breakdown of cost elements for inter-organizational work transfers priced at cost. LMSS CIPS N1.8.5-T1-Estmate-1.0-S3 Revision 2 section 2.3 WPR3 requires this cost element breakdown.</p> <p style="margin: 6pt 0in 0pt 27pt; tab-stops: center 27.0pt left .5in 1.0in 1.5in;">In short, items that are priced as IWTAs have been vetted through the established make/buy process which requires documentation for the factors considered and that sound business and technical judgments have been employed in reaching the make-IWTA decision.</p>',0,0,275);
INSERT INTO [dbo].[Section] ([UpdateDate],[RevisionID],[ID],[ParentID],[DisplayOrder],[Title],[SectionContentTypeID],[TextContent],[IsInternalSection],[DisplayRateCode],[RevisionUniqueSectionId]) VALUES (GETDATE(),1,276,null,9,'System Status',1,'',0,0,276);
