INSERT INTO [dbo].[Section] ([UpdateDate],[RevisionID],[ID],[ParentID],[DisplayOrder],[Title],[SectionContentTypeID],[TextContent],[IsInternalSection],[DisplayRateCode],[RevisionUniqueSectionId]) VALUES (GETDATE(),1,279,278,0,null,2,'<p style="margin: 0in 0in 0pt; tab-stops: -.5in 0in;"><span style="font-family: ''Times New Roman'',serif; font-size: 12pt;">This form <u>will be included</u> in all proposals that require cost or pricing data (this excludes competitive and commercial proposals). It is intended to be filled out by customers and forwarded to DCMA for inclusion into a metric measurement on LMSSC Estimating System.</span></p> <p style="margin: 0in 0in 0pt 0.5in; tab-stops: -.5in;"><span style="font-family: ''Times New Roman'',serif; font-size: 12pt;">&nbsp;</span></p>',0,0,279);
INSERT INTO [dbo].[Section] ([UpdateDate],[RevisionID],[ID],[ParentID],[DisplayOrder],[Title],[SectionContentTypeID],[TextContent],[IsInternalSection],[DisplayRateCode],[RevisionUniqueSectionId]) VALUES (GETDATE(),2,281,null,0,'Introduction',1,'',0,0,1);
INSERT INTO [dbo].[Section] ([UpdateDate],[RevisionID],[ID],[ParentID],[DisplayOrder],[Title],[SectionContentTypeID],[TextContent],[IsInternalSection],[DisplayRateCode],[RevisionUniqueSectionId]) VALUES (GETDATE(),2,282,281,0,null,2,'<p>This document describes the elements of the accounting system used by Lockheed Martin Space Systems Company (LMSSC) and how those elements are calculated and displayed in formal cost proposals.&nbsp; This document is an aide in understanding the Forward Pricing Rate Agreements (FPRAs) and also explains common LMSSC Estimating rates and disclosures.&nbsp;&nbsp; The FPRAs were developed through an IPT process teaming LMSSC, DCMA with inputs from DCAA.&nbsp;&nbsp; Individual proposals will display only the applicable items from this document.&nbsp; The document is intended for use by LMSSC, PCOs, ACOs, oversight agencies, and government cost/price analysts.</p>			',0,0,2);
INSERT INTO [dbo].[Section] ([UpdateDate],[RevisionID],[ID],[ParentID],[DisplayOrder],[Title],[SectionContentTypeID],[TextContent],[IsInternalSection],[DisplayRateCode],[RevisionUniqueSectionId]) VALUES (GETDATE(),2,283,281,1,'Points of Contact',1,'',0,0,3);
