INSERT INTO [dbo].[Section] ([UpdateDate],[RevisionID],[ID],[ParentID],[DisplayOrder],[Title],[SectionContentTypeID],[TextContent],[IsInternalSection],[DisplayRateCode],[RevisionUniqueSectionId]) VALUES (GETDATE(),2,307,293,4,'Offsite Miscellaneous Overhead',1,'',0,0,27);
INSERT INTO [dbo].[Section] ([UpdateDate],[RevisionID],[ID],[ParentID],[DisplayOrder],[Title],[SectionContentTypeID],[TextContent],[IsInternalSection],[DisplayRateCode],[RevisionUniqueSectionId]) VALUES (GETDATE(),2,308,307,0,null,2,'<p>The Offsite Miscellaneous Overhead pool includes the indirect costs of the Offsite Miscellaneous cost centers. Indirect Labor and Non-labor costs include: Restructure, Union Business, Salary Continuation (jury duty, bereavement leave, military leave, sick leave, union business), allocations from Services Total Expense Pool.</p> <p>Base: Direct labor dollars of the cost centers assigned to the Offsite Miscellaneous Pool, Job-shopper costs (if applicable); and applicable labor dollars generated by service centers. This base does not include Michoud Operations.</p>			',0,0,28);
INSERT INTO [dbo].[Section] ([UpdateDate],[RevisionID],[ID],[ParentID],[DisplayOrder],[Title],[SectionContentTypeID],[TextContent],[IsInternalSection],[DisplayRateCode],[RevisionUniqueSectionId]) VALUES (GETDATE(),2,309,307,1,null,3,'			',0,0,29);
