INSERT INTO [dbo].[Section] ([UpdateDate],[RevisionID],[ID],[ParentID],[DisplayOrder],[Title],[SectionContentTypeID],[TextContent],[IsInternalSection],[DisplayRateCode],[RevisionUniqueSectionId]) VALUES (GETDATE(),2,311,293,5,'Huntsville Overhead',1,'',0,0,31);
INSERT INTO [dbo].[Section] ([UpdateDate],[RevisionID],[ID],[ParentID],[DisplayOrder],[Title],[SectionContentTypeID],[TextContent],[IsInternalSection],[DisplayRateCode],[RevisionUniqueSectionId]) VALUES (GETDATE(),2,312,311,0,null,2,'<p>The Huntsville pool includes the indirect costs of cost centers located at the Huntsville site. Indirect Labor and Non-labor costs included: Huntsville Overhead Internal Orders, Huntsville Central Support and Infrastructure, Relocations to Huntsville site, Allocations from Services Total Expense Pool, Abated by amounts charged for occupancy by non-LM employees, Charging for lost time, including facility shutdown, in cases of natural disasters affecting Huntsville.</p> <p>Base: Direct labor dollars of the cost centers assigned to the Huntsville Pool, Job-shopper costs (if applicable); and applicable labor dollars generated by service centers.</p>			',0,0,32);
