INSERT INTO [dbo].[Section] ([UpdateDate],[RevisionID],[ID],[ParentID],[DisplayOrder],[Title],[SectionContentTypeID],[TextContent],[IsInternalSection],[DisplayRateCode],[RevisionUniqueSectionId]) VALUES (GETDATE(),2,316,315,0,null,2,'<p>The Michoud pool includes the indirect costs of cost centers located at the Michoud site. Indirect Labor and Non-labor Costs Included: Michoud Operations Central Support and Infrastructure, Consumable shop supplies and parts and supplies in support of manufacturing, Relocations to Michoud Operations, Charging for sick and lost productive time, including facility shutdown in cases of natural disasters (e.g., hurricane) affecting Michoud Operations, 2008 Only &ndash; Functions, activities and elements of cost as listed for Services Total Pool, Beginning 2009 &ndash; Allocations from Services Total Expense Pool, and Command Media Writing/Reviewing and Audits.</p> <p>Base: Direct labor dollars of the cost centers/departments assigned to the Michoud Operations Pool and Job-shopper total costs.</p>			',0,0,36);
INSERT INTO [dbo].[Section] ([UpdateDate],[RevisionID],[ID],[ParentID],[DisplayOrder],[Title],[SectionContentTypeID],[TextContent],[IsInternalSection],[DisplayRateCode],[RevisionUniqueSectionId]) VALUES (GETDATE(),2,317,315,1,null,3,'			',0,0,37);
