INSERT INTO [dbo].[Section] ([UpdateDate],[RevisionID],[ID],[ParentID],[DisplayOrder],[Title],[SectionContentTypeID],[TextContent],[IsInternalSection],[DisplayRateCode],[RevisionUniqueSectionId]) VALUES (GETDATE(),2,320,319,0,null,2,'<p>The SSC Core Segment Procurement non-labor costs include: Occupancy costs for onsite suppliers and material storage, allocations from the SSC Common Procurement Overhead Pool, Low dollar- high volume (bulk) common material.</p> <p>Base: SSC Core Segment direct material, direct subcontract and consultant costs. Excludes IWTA and Job Shoppers. Also excludes such items not procured by Space Systems Company to support the THAAD program or contracts.</p>			',0,0,40);
INSERT INTO [dbo].[Section] ([UpdateDate],[RevisionID],[ID],[ParentID],[DisplayOrder],[Title],[SectionContentTypeID],[TextContent],[IsInternalSection],[DisplayRateCode],[RevisionUniqueSectionId]) VALUES (GETDATE(),2,321,319,1,null,3,'			',0,0,41);
