INSERT INTO [dbo].[Section] ([UpdateDate],[RevisionID],[ID],[ParentID],[DisplayOrder],[Title],[SectionContentTypeID],[TextContent],[IsInternalSection],[DisplayRateCode],[RevisionUniqueSectionId]) VALUES (GETDATE(),2,323,293,8,'SSC Core Segment General and Administrative (G&A)',1,'',0,0,43);
INSERT INTO [dbo].[Section] ([UpdateDate],[RevisionID],[ID],[ParentID],[DisplayOrder],[Title],[SectionContentTypeID],[TextContent],[IsInternalSection],[DisplayRateCode],[RevisionUniqueSectionId]) VALUES (GETDATE(),2,324,323,0,null,2,'<p>The SSC Core Segment G&amp;A pool includes indirect cost (Labor and Non-labor) of cost centers required for the performance and support of SSC Core Segment G&amp;A Functions, i.e., Chief Engineer, Marketing and Market Analysis, Training for G&amp;A Pool personnel. Corporate research costs, IR&amp;D/B&amp;P projects burdened with applicable overheads, inter-divisional and inter-company costs.</p> <p>Base: SSC Core Segment direct labor dollars, including purchased labor.</p>			',0,0,44);
INSERT INTO [dbo].[Section] ([UpdateDate],[RevisionID],[ID],[ParentID],[DisplayOrder],[Title],[SectionContentTypeID],[TextContent],[IsInternalSection],[DisplayRateCode],[RevisionUniqueSectionId]) VALUES (GETDATE(),2,325,323,1,null,3,'			',0,0,45);
