INSERT INTO [dbo].[Section] ([UpdateDate],[RevisionID],[ID],[ParentID],[DisplayOrder],[Title],[SectionContentTypeID],[TextContent],[IsInternalSection],[DisplayRateCode],[RevisionUniqueSectionId]) VALUES (GETDATE(),2,347,293,14,'SSC Services Segment General and Administrative (G&A)',1,'',0,0,67);
INSERT INTO [dbo].[Section] ([UpdateDate],[RevisionID],[ID],[ParentID],[DisplayOrder],[Title],[SectionContentTypeID],[TextContent],[IsInternalSection],[DisplayRateCode],[RevisionUniqueSectionId]) VALUES (GETDATE(),2,348,347,0,null,2,'<p>The SSC Services Segment G&amp;A pool includes indirect cost (Labor and Non-labor) of cost centers required for the performance and support of SSC Services Segment G&amp;A Functions, i.e., Marketing and Market Analysis, Training for SSC Services Segment G&amp;A Pool personnel, corporate flow- downs, corporate aircraft, state income tax, state income tax, liability insurance, restructure, audit and legal fees, LM Enterprise Business Systems (EBS) allocations, allocation from SSC Home Office Segment, SSC Core Segment U&amp;O, SSC Core Segment Services Total and SSC Core Segment Fringe. Corporate research costs, B&amp;P projects burdened with applicable overhead, inter-divisional and inter-company costs.</p> <p>Base: SSC Services Segment total cost input includes: All SSC Services Segment Labor Dollars, All SSC Services Segment Onsite Services and Offsite Services Overhead pools, All SSC Services Segment other direct costs (ODCs) including travel, rental, material, subcontract costs, etc., All SSC Service Segment Fringe, Intercompany work performed by other Lockheed Martin Business Areas.</p>			',0,0,68);
