INSERT INTO [dbo].[Section] ([UpdateDate],[RevisionID],[ID],[ParentID],[DisplayOrder],[Title],[SectionContentTypeID],[TextContent],[IsInternalSection],[DisplayRateCode],[RevisionUniqueSectionId]) VALUES (GETDATE(),2,351,293,15,'Fringe Lockheed Martin Operations Support (LMOS) / Tier 2',1,'',0,0,71);
INSERT INTO [dbo].[Section] ([UpdateDate],[RevisionID],[ID],[ParentID],[DisplayOrder],[Title],[SectionContentTypeID],[TextContent],[IsInternalSection],[DisplayRateCode],[RevisionUniqueSectionId]) VALUES (GETDATE(),2,352,351,0,null,2,'<p>Costs incurred for SSC Core Segment, SSC Services Segment and SSC Home Office employees in the LMOS Benefits structure: Incentive Compensation and Special Recognition Awards (SRA), Retiree Medical, Group insurance, Workers Compensation, Vacations, Holidays, Hourly Sick Leave, Unemployment Insurance, Social Security, Hourly and Salary Pensions, Deferred Compensation, Supplemental Savings Plan and Administrative Fees.</p> <p>Base: Direct labor dollars of the SSC Core Segment, SSC Services Segment and SSC Home Office employees in the LMOS Benefits structure (excludes labor included in fringe benefits and Contract Labor)</p>			',0,0,72);
