INSERT INTO [dbo].[Section] ([UpdateDate],[RevisionID],[ID],[ParentID],[DisplayOrder],[Title],[SectionContentTypeID],[TextContent],[IsInternalSection],[DisplayRateCode],[RevisionUniqueSectionId]) VALUES (GETDATE(),2,355,293,16,'Facilities Capital Cost Of Money (FCCOM)',1,'',0,0,75);
INSERT INTO [dbo].[Section] ([UpdateDate],[RevisionID],[ID],[ParentID],[DisplayOrder],[Title],[SectionContentTypeID],[TextContent],[IsInternalSection],[DisplayRateCode],[RevisionUniqueSectionId]) VALUES (GETDATE(),2,356,355,0,'FCCOM',1,'',0,0,76);
INSERT INTO [dbo].[Section] ([UpdateDate],[RevisionID],[ID],[ParentID],[DisplayOrder],[Title],[SectionContentTypeID],[TextContent],[IsInternalSection],[DisplayRateCode],[RevisionUniqueSectionId]) VALUES (GETDATE(),2,357,356,0,null,2,'<p>FCCOM will be included as an element of the cost/price offer for all cost-reimbursement contracts with the United States Government, except in the situation of modifications to existing contracts where FAR Clause 52.215-17 &ndash; &ldquo;Waiver of Facilities Capital Cost of Money&rdquo; has already been incorporated.</p> <p>The 2017-2019 &amp; On CAS 414 rates, reference letters FPRA 16-04 dated July 8, 2016<br />The 2016 actual overhead rates, reference LMSSC-17-003 memo dated January 11, 2017<br />The 2015 actual CAS 414 rates, reference letter LMSSC-16-001 memo dated January 8, 2016<br />The 2014 actual CAS 414 rates, reference letter LMSSC-15-001 memo dated January 9, 2015</p> <p>FCCOM rates are applied to dollars associated with each pool (reference Overhead base).</p>			',0,0,77);
INSERT INTO [dbo].[Section] ([UpdateDate],[RevisionID],[ID],[ParentID],[DisplayOrder],[Title],[SectionContentTypeID],[TextContent],[IsInternalSection],[DisplayRateCode],[RevisionUniqueSectionId]) VALUES (GETDATE(),2,358,356,1,null,3,'			',0,1,78);
