INSERT INTO [dbo].[Section] ([UpdateDate],[RevisionID],[ID],[ParentID],[DisplayOrder],[Title],[SectionContentTypeID],[TextContent],[IsInternalSection],[DisplayRateCode],[RevisionUniqueSectionId]) VALUES (GETDATE(),2,399,397,1,null,3,'			',0,0,119);
INSERT INTO [dbo].[Section] ([UpdateDate],[RevisionID],[ID],[ParentID],[DisplayOrder],[Title],[SectionContentTypeID],[TextContent],[IsInternalSection],[DisplayRateCode],[RevisionUniqueSectionId]) VALUES (GETDATE(),2,400,397,2,null,2,'<p style="margin: 0in; margin-bottom: .0001pt;"><span style="color: black;">(FPRA 16-06 Rev 1, dated September 19, 2016)</span></p> <p style="margin: 0in; margin-bottom: .0001pt;"><span style="color: black;">&nbsp;</span></p> <p style="margin: 0in; margin-bottom: .0001pt;"><strong><span style="color: black;">Salaried Labor Rate Escalation for years beyond Agreement (Non-represented Labor Level A through Labor Level E)</span></strong></p> <p style="margin: 0in; margin-bottom: .0001pt;"><span style="color: black;">&nbsp;</span></p> <p style="margin: 0in; margin-bottom: .0001pt;"><span style="color: black;">Lockheed Martin Space Systems (LMSSC) consults a variety of sources (both internal to LM and external) when forecasting labor rate escalation.&nbsp; As uncertainty and risk increase in the out years, escalation trends tend to increase.&nbsp; Based on economic forecast data and industry trends, LMSSC forecast a Heritage labor escalation of 3% for years 2021 &amp; On and 3% escalation for years 2020 &amp; beyond for Mission Solutions.&nbsp; This escalation is not a submitted or negotiated rate.</span></p> <p style="margin: 0in; margin-bottom: .0001pt;"><span style="color: black; background: yellow;">&nbsp;</span></p> <p style="margin: 0in; margin-bottom: .0001pt;"><strong><span style="color: black;">Union Represented Labor Rate Escalation for years 2021</span></strong> <strong><span style="color: black;">&amp; On (Level A - Heritage)</span></strong></p> <p style="margin: 0in; margin-bottom: .0001pt;"><strong><span style="color: black;">&nbsp;</span></strong></p> <p style="margin: 0in; margin-bottom: .0001pt;"><span style="color: black;">Escalation for Level A union represented employees are based on Collective Bargaining Agreements (CBAs).&nbsp; Current union contract conditions used for calculating the escalation percentage are replicated for future years.</span></p>			',0,0,120);
INSERT INTO [dbo].[Section] ([UpdateDate],[RevisionID],[ID],[ParentID],[DisplayOrder],[Title],[SectionContentTypeID],[TextContent],[IsInternalSection],[DisplayRateCode],[RevisionUniqueSectionId]) VALUES (GETDATE(),2,401,391,3,'Non-Labor (Material, ODC etc.) Escalation Percentage & Compounded Escalation Factor',1,'',0,0,121);
INSERT INTO [dbo].[Section] ([UpdateDate],[RevisionID],[ID],[ParentID],[DisplayOrder],[Title],[SectionContentTypeID],[TextContent],[IsInternalSection],[DisplayRateCode],[RevisionUniqueSectionId]) VALUES (GETDATE(),2,402,401,0,null,2,'<p>The Non-Labor Escalation rates provided below are <u>not negotiated</u> but are recommended for use. Justification and data sources are required when using alternative escalation rates.</p> <p>&nbsp;</p> <p>Non-labor escalation is from the IHS Global Insight, Pricing and Purchasing <span style="color: black;">Service, </span><span style="color: red;">3rd </span><span style="color: black;">Quarter </span>2017, Defense/Aerospace Prices and Wages, Aerospace Products and Parts Manufacturing (PPI3364).&nbsp; <span style="color: red;">Years 2028 and on are a 6 year average of 2022 &ndash; 2027 rates.</span></p>',0,0,122);
INSERT INTO [dbo].[Section] ([UpdateDate],[RevisionID],[ID],[ParentID],[DisplayOrder],[Title],[SectionContentTypeID],[TextContent],[IsInternalSection],[DisplayRateCode],[RevisionUniqueSectionId]) VALUES (GETDATE(),2,403,401,1,null,3,'			',0,0,123);
INSERT INTO [dbo].[Section] ([UpdateDate],[RevisionID],[ID],[ParentID],[DisplayOrder],[Title],[SectionContentTypeID],[TextContent],[IsInternalSection],[DisplayRateCode],[RevisionUniqueSectionId]) VALUES (GETDATE(),2,404,391,4,'Travel Escalation Percentage & Compounded Escalation Factor',1,'',0,0,124);
INSERT INTO [dbo].[Section] ([UpdateDate],[RevisionID],[ID],[ParentID],[DisplayOrder],[Title],[SectionContentTypeID],[TextContent],[IsInternalSection],[DisplayRateCode],[RevisionUniqueSectionId]) VALUES (GETDATE(),2,405,404,0,null,2,'<p>The Travel Escalation rates provided below are <u>not negotiated</u> but are recommended for use. Justification and data sources are required when using alternative escalation rates.</p> <p>&nbsp;</p> <p>Travel escalation is based on a weighted average of the following elements from the IHS Global</p> <p>Insight, Pricing and Purchasing Service,<span style="color: red;"> 3rd </span><span style="color: black;">Quarter 2017.</span></p> <p><span style="color: black;">Corporate Expenses, CPI, Airfares; Lodging Away from Home</span>; Restaurant Meals; PPI Passenger Car Rental; Other - CPI, All Items, Urban (Aggregate Price)</p> <p>&nbsp;</p> <p>Note: 2017-2019 have been adjusted to remove rental car.&nbsp; The current rental car agreement has a negotiated rate for these years.&nbsp; <span style="color: red;">The 2028 rate is used for 2029 and on.</span></p>',0,0,125);
INSERT INTO [dbo].[Section] ([UpdateDate],[RevisionID],[ID],[ParentID],[DisplayOrder],[Title],[SectionContentTypeID],[TextContent],[IsInternalSection],[DisplayRateCode],[RevisionUniqueSectionId]) VALUES (GETDATE(),2,406,404,1,null,3,'			',0,0,126);
INSERT INTO [dbo].[Section] ([UpdateDate],[RevisionID],[ID],[ParentID],[DisplayOrder],[Title],[SectionContentTypeID],[TextContent],[IsInternalSection],[DisplayRateCode],[RevisionUniqueSectionId]) VALUES (GETDATE(),2,407,391,5,'Service Center Escalation',1,'',0,0,127);
INSERT INTO [dbo].[Section] ([UpdateDate],[RevisionID],[ID],[ParentID],[DisplayOrder],[Title],[SectionContentTypeID],[TextContent],[IsInternalSection],[DisplayRateCode],[RevisionUniqueSectionId]) VALUES (GETDATE(),2,408,407,0,null,2,'<p style="margin: 0in; margin-bottom: .0001pt;"><span style="color: black;">Functional and Line of Business Service Center Rates in Section 5.0 are displayed through 2019.&nbsp; Rates beyond 2019 are escalated using the following labor and non-labor escalation rates. </span></p> <p style="margin: 0in; margin-bottom: .0001pt;"><span style="color: red;">&nbsp;</span></p> <p>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; Core Segment Service Centers</p> <table style="width: 171.05pt; margin-left: 4.65pt; border-collapse: collapse; border: none;"> <tbody> <tr style="height: 15.75pt;"> <td style="width: 82.85pt; border: solid black 1.0pt; padding: 0in 5.4pt 0in 5.4pt; height: 15.75pt;"> <p style="text-align: right;">&nbsp;</p> </td> <td style="width: 10.65pt; border: solid black 1.0pt; border-left: none; padding: 0in 5.4pt 0in 5.4pt; height: 15.75pt;"> <p style="text-align: center;">&nbsp;</p> </td> <td style="width: 77.55pt; border: solid black 1.0pt; border-left: none; padding: 0in 5.4pt 0in 5.4pt; height: 15.75pt;"> <p style="text-align: center;">2020 &amp; On</p> </td> </tr> <tr style="height: 15.75pt;"> <td style="width: 82.85pt; border: solid black 1.0pt; border-top: none; padding: 0in 5.4pt 0in 5.4pt; height: 15.75pt;"> <p style="text-align: center;">Labor</p> </td> <td style="width: 10.65pt; border-top: none; border-left: none; border-bottom: solid black 1.0pt; border-right: solid black 1.0pt; padding: 0in 5.4pt 0in 5.4pt; height: 15.75pt;"> <p style="text-align: right;">&nbsp;</p> </td> <td style="width: 77.55pt; border-top: none; border-left: none; border-bottom: solid black 1.0pt; border-right: solid black 1.0pt; padding: 0in 5.4pt 0in 5.4pt; height: 15.75pt;"> <p style="text-align: right;">3.00%</p> </td> </tr> <tr style="height: 15.75pt;"> <td style="width: 82.85pt; border: solid black 1.0pt; border-top: none; padding: 0in 5.4pt 0in 5.4pt; height: 15.75pt;"> <p style="text-align: center;">Non-Labor</p> </td> <td style="width: 10.65pt; border-top: none; border-left: none; border-bottom: solid black 1.0pt; border-right: solid black 1.0pt; padding: 0in 5.4pt 0in 5.4pt; height: 15.75pt;"> <p style="text-align: right;">&nbsp;</p> </td> <td style="width: 77.55pt; border-top: none; border-left: none; border-bottom: solid black 1.0pt; border-right: solid black 1.0pt; padding: 0in 5.4pt 0in 5.4pt; height: 15.75pt;"> <p style="text-align: right;">2.34%</p> </td> </tr> </tbody> </table> <p>&nbsp;</p> <p style="margin: 0in; margin-bottom: .0001pt;"><span style="color: black;">Reference FPRA 16-05 (Core Segment Service Centers) </span></p> <p>&nbsp;</p> <p>&nbsp;</p> <p>&nbsp;&nbsp; Mission Solutions Service Center</p> <table style="width: 171.05pt; margin-left: 4.65pt; border-collapse: collapse; border: none;"> <tbody> <tr style="height: 15.75pt;"> <td style="width: 82.85pt; border: solid black 1.0pt; padding: 0in 5.4pt 0in 5.4pt; height: 15.75pt;"> <p style="text-align: right;">&nbsp;</p> </td> <td style="width: 10.65pt; border: solid black 1.0pt; border-left: none; padding: 0in 5.4pt 0in 5.4pt; height: 15.75pt;"> <p style="text-align: center;">&nbsp;</p> </td> <td style="width: 77.55pt; border: solid black 1.0pt; border-left: none; padding: 0in 5.4pt 0in 5.4pt; height: 15.75pt;"> <p style="text-align: center;">2020 &amp; On</p> </td> </tr> <tr style="height: 15.75pt;"> <td style="width: 82.85pt; border: solid black 1.0pt; border-top: none; padding: 0in 5.4pt 0in 5.4pt; height: 15.75pt;"> <p style="text-align: center;">Labor</p> </td> <td style="width: 10.65pt; border-top: none; border-left: none; border-bottom: solid black 1.0pt; border-right: solid black 1.0pt; padding: 0in 5.4pt 0in 5.4pt; height: 15.75pt;"> <p style="text-align: right;">&nbsp;</p> </td> <td style="width: 77.55pt; border-top: none; border-left: none; border-bottom: solid black 1.0pt; border-right: solid black 1.0pt; padding: 0in 5.4pt 0in 5.4pt; height: 15.75pt;"> <p style="text-align: right;">3.00%</p> </td> </tr> <tr style="height: 15.75pt;"> <td style="width: 82.85pt; border: solid black 1.0pt; border-top: none; padding: 0in 5.4pt 0in 5.4pt; height: 15.75pt;"> <p style="text-align: center;">Non-Labor</p> </td> <td style="width: 10.65pt; border-top: none; border-left: none; border-bottom: solid black 1.0pt; border-right: solid black 1.0pt; padding: 0in 5.4pt 0in 5.4pt; height: 15.75pt;"> <p style="text-align: right;">&nbsp;</p> </td> <td style="width: 77.55pt; border-top: none; border-left: none; border-bottom: solid black 1.0pt; border-right: solid black 1.0pt; padding: 0in 5.4pt 0in 5.4pt; height: 15.75pt;"> <p style="text-align: right;">2.45%</p> </td> </tr> </tbody> </table> <p>&nbsp;</p> <p style="margin: 0in; margin-bottom: .0001pt;"><span style="color: black;">LMSSC 16-009 (Mission Solutions Service Center), dated February 1, 2016 </span></p>',0,0,128);
