INSERT INTO [dbo].[Section] ([UpdateDate],[RevisionID],[ID],[ParentID],[DisplayOrder],[Title],[SectionContentTypeID],[TextContent],[IsInternalSection],[DisplayRateCode],[RevisionUniqueSectionId]) VALUES (GETDATE(),2,422,421,0,null,2,'<p>Effort required to develop and implement engineering tools used by programs; process implementation; development and maintenance of engineering databases, such as those used by Parts/Materials/Processes; Engineering budget administration; management oversight of deployed engineering resources, including Human Resource Business Partners supporting Engineering; Engineering Labs supervisors; and labor and non-labor costs related to centralized engineering workstations and computing capabilities that support multiple existing programs.</p> <p>Base = Direct labor hours charged to contracts by employees assigned to Engineering Sending Cost Centers in Development Overhead Pool (Core Segment)<br />Result = Labor cost in Development Pool and ODC dollars</p>			',0,0,142);
INSERT INTO [dbo].[Section] ([UpdateDate],[RevisionID],[ID],[ParentID],[DisplayOrder],[Title],[SectionContentTypeID],[TextContent],[IsInternalSection],[DisplayRateCode],[RevisionUniqueSectionId]) VALUES (GETDATE(),2,423,421,1,null,3,'			',0,0,143);
