INSERT INTO [dbo].[Section] ([UpdateDate],[RevisionID],[ID],[ParentID],[DisplayOrder],[Title],[SectionContentTypeID],[TextContent],[IsInternalSection],[DisplayRateCode],[RevisionUniqueSectionId]) VALUES (GETDATE(),2,425,411,4,'541155 - Test Labs Service Center',1,'',0,0,145);
INSERT INTO [dbo].[Section] ([UpdateDate],[RevisionID],[ID],[ParentID],[DisplayOrder],[Title],[SectionContentTypeID],[TextContent],[IsInternalSection],[DisplayRateCode],[RevisionUniqueSectionId]) VALUES (GETDATE(),2,426,425,0,null,2,'<p>SSC labor and non-labor cost incurred to supervise and support operation of Test Labs. Effort includes labs supervision (manpower planning, salary management and staffing), business operation (management and clerical support, budget tracking, procurement support and property management, Certified Test Conductor and technical training programs), and operations and facilities management. Non-labor cost includes expendable and consumable operating supplies applicable to multiple programs and effective 1/1/08 depreciation for fixed asset tooling and equipment used in Test Labs.</p> <p>Base = Direct labor hours charged to contracts by personnel assigned to Test Labs Sending Cost Centers in the Development Overhead Pool (Core Segment)<br />Result = Labor cost in Development Pool and ODC dollars</p>			',0,0,146);
INSERT INTO [dbo].[Section] ([UpdateDate],[RevisionID],[ID],[ParentID],[DisplayOrder],[Title],[SectionContentTypeID],[TextContent],[IsInternalSection],[DisplayRateCode],[RevisionUniqueSectionId]) VALUES (GETDATE(),2,427,425,1,null,3,'			',0,0,147);
