INSERT INTO [dbo].[Section] ([UpdateDate],[RevisionID],[ID],[ParentID],[DisplayOrder],[Title],[SectionContentTypeID],[TextContent],[IsInternalSection],[DisplayRateCode],[RevisionUniqueSectionId]) VALUES (GETDATE(),2,429,411,5,'541175 - Production Service Center',1,'',0,0,149);
INSERT INTO [dbo].[Section] ([UpdateDate],[RevisionID],[ID],[ParentID],[DisplayOrder],[Title],[SectionContentTypeID],[TextContent],[IsInternalSection],[DisplayRateCode],[RevisionUniqueSectionId]) VALUES (GETDATE(),2,430,429,0,null,2,'<p>SSC labor and non-labor costs incurred for multi-program activity in support of Production personnel. Tasks include, but not limited to management, supervision and technical interface performed by leaders and Production personnel in meeting program requirements, Resource Management, Human Resources, oversight and administrative effort. Process control testing, lab test method development and verification, ESD certification, material management, stock sweeps, methods and area engineering, manufacturing process instruction (MPI) maintenance. Includes pagers, cell phones, and other comparable communications devices; travel expense incurred supporting multi-program requirements and related coordination, status and reporting efforts. Effort excludes support of FBM manufacturing cost centers and remote sites. Production web server technical information integration, depreciation, and maintenance to support multi-program compliance. EBS system administration and user support cost allocations.</p> <p>Base = Direct labor hours in Manufacturing Touch Sending Cost Centers in the Production Overhead Pool excluding Fleet Ballistic Missile (FBM) Manufacturing Touch Sending Cost Centers<br />Result = Labor cost in Production Pool and ODC dollars</p>			',0,0,150);
