INSERT INTO [dbo].[Section] ([UpdateDate],[RevisionID],[ID],[ParentID],[DisplayOrder],[Title],[SectionContentTypeID],[TextContent],[IsInternalSection],[DisplayRateCode],[RevisionUniqueSectionId]) VALUES (GETDATE(),2,434,433,0,null,2,'<p>SSC labor and non-labor costs includes Product and Strategic, supervision and administrative support of Quality Assurance personnel, including Human Resource Business Partners support Quality. Includes Corrective Action Board meetings and assessments, request and actions; collection, generation and analysis of Quality metrics and reviews; Audit support (e.g. BSI, Customer and internal audits), Out of Tolerance Notifications, identification and related processing of calibration requirements and maintenance activities for common equipment/tools/facilities, and area surveillance; Quality Planning and Material Review Board certification/activities; GIDEP alerts, stock sweep activities; Error Prevention coordination, planning and control of service center costs.</p> <p>Also includes Programs and Quality department administration efforts and pages, cell phones and other comparable communication devices.</p> <p>Base = Direct labor hours in Quality Sending Cost Centers in the Development Overhead Pool (Core Segment)<br />Result = Labor cost in Development Pool and ODC dollars</p>			',0,0,154);
INSERT INTO [dbo].[Section] ([UpdateDate],[RevisionID],[ID],[ParentID],[DisplayOrder],[Title],[SectionContentTypeID],[TextContent],[IsInternalSection],[DisplayRateCode],[RevisionUniqueSectionId]) VALUES (GETDATE(),2,435,433,1,null,3,'			',0,0,155);
