INSERT INTO [dbo].[Section] ([UpdateDate],[RevisionID],[ID],[ParentID],[DisplayOrder],[Title],[SectionContentTypeID],[TextContent],[IsInternalSection],[DisplayRateCode],[RevisionUniqueSectionId]) VALUES (GETDATE(),2,522,521,0,null,2,'<p style="tab-stops: 0in .5in 1.0in; text-autospace: none;">Computing services (<em>administrative, batch, and/or interactive</em>) for each of the following systems:</p> <ul> <li style="margin-left: .75in; text-indent: -.25in; tab-stops: 0in .5in 1.0in; text-autospace: none;">Business (Cost Center 5422BC)</li> <li style="margin-left: .75in; text-indent: -.25in; tab-stops: 0in .5in 1.0in; text-autospace: none;">Virtual Machine (Cost Center 5422VM)</li> <li style="margin-left: .75in; text-indent: -.25in; tab-stops: 0in .5in 1.0in; text-autospace: none;">VAX (Cost Center 5122VA)</li> </ul> <p>SSC direct labor travel costs, equipment, gain or loss on disposal of the equipment, software (including internally developed software and amortization of capitalized software), data processing supplies, vendor computing costs, inter-company work transfers from Lockheed Martin Enterprise Business Systems (EBS), and distributed computing &amp; telecommunications and data center services charges from EBS. This Service Center cost is allocated to only SSC, Sunnyvale Service Centers that incur EBS labor hours.</p> <p>The base for application of the rates is computer units. Shared Computer Service Center Rates are not included in the current FPRA. Any computing service costs related to these systems should be proposed as a factor.</p>			',0,0,242);
